// Workflow 14, JOB A (Welle 3, AP5): Portfoliorisiko-Pruefung + Paper-Trade-
// Anlage fuer heute von "06" neu geoeffnete Empfehlungen. Laeuft NACH "06" -
// Bestaetigung/DRY_RUN ist zu diesem Zeitpunkt bereits aufgeloest (siehe
// docs/PORTFOLIORISIKO.md fuer die Begruendung dieser Reihenfolge). Ein vom
// Portfoliorisiko blockierter Trade bekommt trotzdem eine paper_trades-Zeile
// (status='blocked') - vollstaendige Historie statt stillem Verwerfen.

function round(v, d = 4) { if (v === null || v === undefined || isNaN(v)) return null; return parseFloat(Number(v).toFixed(d)); }
function num(v) { const n = Number(v); return v === null || v === undefined || v === '' || isNaN(n) ? null : n; }

function getBusinessDate(date = new Date()) {
  return new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Berlin', year: 'numeric', month: '2-digit', day: '2-digit' }).format(date);
}
const heute = getBusinessDate();
// FIX 2026-08-02 (Fehleranalyse B9): Date.now() machte run_id bei jedem Lauf eindeutig,
// auch am selben Tag - ein Wiederholungslauf konnte nie als Duplikat erkannt werden.
// Deterministisch pro Tag, damit UNIQUE(run_id, ticker) auf portfolio_risk_checks greift.
const run_id = 'p14a-' + heute;
const RISK_MODEL_VERSION = 'welle3-portfolio-v1';

const CFG = {};
for (const r of $('DB: Portfolio-Konfiguration laden').all().map(i => i.json)) CFG[r.config_key] = Number(r.value_numeric);
const MODEL_PORTFOLIO_VALUE = CFG.MODEL_PORTFOLIO_VALUE ?? 100000;
const MAX_TOTAL_OPEN_RISK_PCT = CFG.MAX_TOTAL_OPEN_RISK_PCT ?? 6.0;
const MAX_SECTOR_EXPOSURE_PCT = CFG.MAX_SECTOR_EXPOSURE_PCT ?? 15.0;
const MAX_SINGLE_POSITION_PCT = CFG.MAX_SINGLE_POSITION_PCT ?? 8.0;
const MAX_OPEN_POSITIONS = CFG.MAX_OPEN_POSITIONS ?? 10;
const MAX_DIRECTIONAL_EXPOSURE_PCT = CFG.MAX_DIRECTIONAL_EXPOSURE_PCT ?? 40.0;
const MAX_PORTFOLIO_DRAWDOWN_PCT = CFG.MAX_PORTFOLIO_DRAWDOWN_PCT ?? 15.0;
const CORRELATION_LOOKBACK_DAYS = CFG.CORRELATION_LOOKBACK_DAYS ?? 60;
const MAX_PAIRWISE_CORRELATION = CFG.MAX_PAIRWISE_CORRELATION ?? 0.75;
const STRESS_RISK_REDUCTION_FACTOR = CFG.STRESS_RISK_REDUCTION_FACTOR ?? 0.5;
// FIX 2026-08-02 (Welle-3-Abgleich, Fund 2/5): Region-/Waehrungs-Expositionslimits, bisher
// gar nicht geprueft (region floss nur ins Regime-Lookup ein, nicht als Limit).
const MAX_REGION_EXPOSURE_PCT = CFG.MAX_REGION_EXPOSURE_PCT ?? 60.0;
const MAX_NON_EUR_EXPOSURE_PCT = CFG.MAX_NON_EUR_EXPOSURE_PCT ?? 30.0;
// FIX (Haertung Welle 1-3, Phase 7): Dead-Letter-Schwelle fuer Empfehlungen, die aus
// unbekanntem Grund wiederholt als portfolio_pending geladen werden (siehe unten).
const MAX_PORTFOLIO_CHECK_ATTEMPTS = CFG.MAX_PORTFOLIO_CHECK_ATTEMPTS ?? 5;

const neueEmpfehlungen = $('DB: Heutige neue Empfehlungen laden').all().map(i => i.json).filter(e => e && e.id != null && e.ticker != null); // FIX 2026-08-17 (erster Live-Test): alwaysOutputData auf dem Quellnode injiziert bei 0 echten Zeilen ein Phantom-Item (id/ticker=undefined) - ungefiltert fuehrte das zu einem NOT-NULL-Verstoss auf portfolio_risk_checks.ticker.
// FIX 2026-08-02 (Fehleranalyse B6): eigene, von 06 unabhaengige DRY_RUN-Pruefung als
// Verteidigung in der Tiefe - 14 verliess sich bisher vollstaendig darauf, dass 06 im
// DRY_RUN-Fall keine neuen Empfehlungen schreibt. Gleicher sicherer Fallback wie in 06/00
// (Fehleranalyse B4): fehlender/NULL-Konfigwert faellt auf true (sicherer Pfad), nicht false.
const dryRunRow = $('DB: Portfolio-Konfiguration laden').all().map(i => i.json).find(r => r.config_key === 'DRY_RUN');
const DRY_RUN = dryRunRow && dryRunRow.value_bool !== null && dryRunRow.value_bool !== undefined ? dryRunRow.value_bool === true : true;
if (DRY_RUN && neueEmpfehlungen.length > 0) {
  console.warn('DRY_RUN aktiv (B6-Verteidigung in der Tiefe): ' + neueEmpfehlungen.length + ' neue Empfehlung(en) von 06 vorhanden, werden trotzdem nur simuliert (keine echten Schreibvorgaenge) - erwartet waere 0, da 06 im DRY_RUN keine neuen Empfehlungen schreiben sollte.');
}
const offenePaperTrades = $('DB: Offene Paper-Trades laden').all().map(i => i.json);
const geschlossenePaperTrades = $('DB: Geschlossene Paper-Trades laden (Drawdown)').all().map(i => i.json);
const regimeRows = $('DB: Marktregime laden (Portfolio)').all().map(i => i.json);
const priceRows = $('DB: Kursverlauf laden (Korrelation)').all().map(i => i.json);
const strategyStatusRows = $('DB: Strategie-Status laden').all().map(i => i.json);
// FIX 2026-08-02 (Welle-3-Abgleich, Fund 2/5): Region/Waehrung je Ticker (aus
// trading.stock_instruments.exchange/currency, gleiches Ableitungsmuster wie in 06).
const regionWaehrungRows = $('DB: Ticker-Region-Waehrung laden').all().map(i => i.json);
const regionByTicker = {}, waehrungByTicker = {};
for (const r of regionWaehrungRows) { regionByTicker[r.ticker] = r.region; waehrungByTicker[r.ticker] = r.currency; }

const regimeByRegion = {}; for (const r of regimeRows) regimeByRegion[r.region] = r;
const strategyAktivByName = {}; for (const s of strategyStatusRows) strategyAktivByName[s.strategy] = s.aktiv === true || s.aktiv === 'true';

const priceByTicker = {};
for (const p of priceRows) { const k = String(p.symbol || '').trim(); if (!priceByTicker[k]) priceByTicker[k] = []; priceByTicker[k].push(p); }
for (const k of Object.keys(priceByTicker)) priceByTicker[k].sort((a, b) => String(a.trading_date).localeCompare(String(b.trading_date)));
function dailyReturns(ticker) {
  const rows = (priceByTicker[ticker] || []).slice(-(CORRELATION_LOOKBACK_DAYS + 1));
  const closes = rows.map(r => Number(r.close)).filter(v => !isNaN(v));
  const rets = [];
  for (let i = 1; i < closes.length; i++) if (closes[i - 1] > 0) rets.push((closes[i] - closes[i - 1]) / closes[i - 1]);
  return rets;
}
function pearson(a, b) {
  const n = Math.min(a.length, b.length);
  if (n < 10) return null;
  const av = a.slice(-n), bv = b.slice(-n);
  const meanA = av.reduce((x, y) => x + y, 0) / n, meanB = bv.reduce((x, y) => x + y, 0) / n;
  let cov = 0, varA = 0, varB = 0;
  for (let i = 0; i < n; i++) { cov += (av[i] - meanA) * (bv[i] - meanB); varA += (av[i] - meanA) ** 2; varB += (bv[i] - meanB) ** 2; }
  if (varA === 0 || varB === 0) return null;
  return cov / Math.sqrt(varA * varB);
}

// FIX 2026-08-01 (Fehleranalyse E5, kritisch): equity/peak starteten bei 0 statt beim
// Startkapital. Bei einer anfaenglichen Verlustserie blieb equity dauerhaft negativ, peak
// dauerhaft 0 (peak>0-Bedingung griff nie) - der Drawdown-Blocker konnte in dieser Phase
// NIE ausloesen, egal wie hoch der reale Verlust war.
geschlossenePaperTrades.sort((a, b) => String(a.exit_time).localeCompare(String(b.exit_time)));
let equity = MODEL_PORTFOLIO_VALUE, peak = MODEL_PORTFOLIO_VALUE, maxDrawdownPct = 0;
// FIX 2026-08-02 (Fehleranalyse E6): Nenner war die Konstante MODEL_PORTFOLIO_VALUE statt des
// laufenden Hochs peak_t (Auftragsformel: (peak_t-equity_t)/peak_t*100). Echter Verhaltens-
// unterschied, kein reines Kosmetikproblem: peak_t >= MODEL_PORTFOLIO_VALUE immer (peak faellt
// nie unter das Startkapital), die alte Formel ueberzeichnete den Drawdown also systematisch
// nach jeder Gewinnphase und liess den DRAWDOWN_LIMIT-Veto zu frueh ausloesen. Deckungsgleich
// mit der alten Formel, solange equity nie ueber das Startkapital gestiegen ist (peak bleibt
// dann == MODEL_PORTFOLIO_VALUE).
for (const t of geschlossenePaperTrades) {
  equity += Number(t.net_pnl) || 0;
  if (equity > peak) peak = equity;
  const dd = peak > 0 ? ((peak - equity) / peak) * 100 : 0;
  if (dd > maxDrawdownPct) maxDrawdownPct = dd;
}
const aktuellerDrawdownPct = peak > 0 ? ((peak - equity) / peak) * 100 : 0;

function offeneSumme(feld, filterFn) {
  return offenePaperTrades.filter(filterFn || (() => true)).reduce((sum, t) => sum + (Number(t[feld]) || 0), 0);
}

// FIX 2026-08-01 (Fehleranalyse E1, kritisch): ohne deterministische Sortierung entschied
// die undefinierte physische Postgres-Zeilenreihenfolge, welcher Kandidat bei einem knappen
// gemeinsamen Limit zuerst (und damit bevorzugt) geprueft wird. Sortierung: is_theoretical
// (bereits bestaetigt vor noch-theoretisch) -> opportunity_score (Qualitaet) ->
// reward_risk_ratio (Chance-Risiko) -> evidence_confidence (Konfidenz) -> ticker
// (deterministischer Tiebreaker).
function sortKey(e) {
  return [
    e.is_theoretical === false ? 0 : 1,
    -(Number(e.opportunity_score) || 0),
    -(Number(e.reward_risk_ratio) || 0),
    -(Number(e.evidence_confidence) || 0),
    String(e.ticker || '')
  ];
}
neueEmpfehlungen.sort((a, b) => {
  const ka = sortKey(a), kb = sortKey(b);
  for (let i = 0; i < ka.length; i++) {
    if (ka[i] < kb[i]) return -1;
    if (ka[i] > kb[i]) return 1;
  }
  return 0;
});

const output = [];
let sequenceIndex = 0;
for (const empf of neueEmpfehlungen) {
  sequenceIndex++;
  const ticker = empf.ticker;
  const region = empf.market_regime_region || 'Europa';
  const regime = regimeByRegion[region] || null;
  const istStress = regime && regime.combined_regime === 'stress';

  const blockers = [];

  // Strategie global deaktiviert? (AP9-Aktivierungspfad)
  if (empf.strategy && strategyAktivByName[empf.strategy] === false) {
    blockers.push({ code: 'STRATEGY_DEACTIVATED', message: 'Strategie ' + empf.strategy + ' ist ueber einen aktivierten Lernvorschlag global deaktiviert.' });
  }

  const risikoVorher = offeneSumme('risk_amount');
  const risikoDanach = risikoVorher + (Number(empf.risk_amount) || 0);
  const portfolioRiskBefore = round(risikoVorher / MODEL_PORTFOLIO_VALUE, 5);
  const portfolioRiskAfter = round(risikoDanach / MODEL_PORTFOLIO_VALUE, 5);
  const effectiveMaxTotalRiskPct = istStress ? MAX_TOTAL_OPEN_RISK_PCT * STRESS_RISK_REDUCTION_FACTOR : MAX_TOTAL_OPEN_RISK_PCT;
  if (portfolioRiskAfter * 100 > effectiveMaxTotalRiskPct) {
    blockers.push({ code: 'TOTAL_RISK_LIMIT', message: 'Gesamtes offenes Stoprisiko wuerde ' + (portfolioRiskAfter * 100).toFixed(2) + '% uebersteigen (Limit ' + effectiveMaxTotalRiskPct.toFixed(2) + '%' + (istStress ? ', stressreduziert' : '') + ')' });
  }

  const sektorWert = offeneSumme('position_value', t => t.sektor === empf.sektor) + (Number(empf.position_value) || 0);
  if ((sektorWert / MODEL_PORTFOLIO_VALUE) * 100 > MAX_SECTOR_EXPOSURE_PCT) {
    blockers.push({ code: 'SECTOR_LIMIT', message: 'Sektor ' + empf.sektor + ' ueberschreitet das konfigurierte Limit (' + MAX_SECTOR_EXPOSURE_PCT + '%)' });
  }

  // FIX 2026-08-02 (Welle-3-Abgleich, Fund 2/5): Region- und Waehrungs-Exposition, gleiches
  // Muster wie die Sektorpruefung oben. offenePaperTrades traegt ticker (siehe E2-Fix), Region/
  // Waehrung werden hier je Ticker nachgeschlagen statt auf offenePaperTrades vorgehalten zu
  // werden - weniger Redundanz, ein Blick in die Map reicht.
  const empfRegion = regionByTicker[ticker] || 'global';
  const regionWert = offeneSumme('position_value', t => (regionByTicker[t.ticker] || 'global') === empfRegion) + (Number(empf.position_value) || 0);
  if ((regionWert / MODEL_PORTFOLIO_VALUE) * 100 > MAX_REGION_EXPOSURE_PCT) {
    blockers.push({ code: 'REGION_LIMIT', message: 'Region ' + empfRegion + ' ueberschreitet das konfigurierte Limit (' + MAX_REGION_EXPOSURE_PCT + '%)' });
  }

  const empfWaehrung = waehrungByTicker[ticker] || 'EUR';
  if (empfWaehrung !== 'EUR') {
    const nonEurWert = offeneSumme('position_value', t => (waehrungByTicker[t.ticker] || 'EUR') !== 'EUR') + (Number(empf.position_value) || 0);
    if ((nonEurWert / MODEL_PORTFOLIO_VALUE) * 100 > MAX_NON_EUR_EXPOSURE_PCT) {
      blockers.push({ code: 'CURRENCY_LIMIT', message: 'Nicht-EUR-Exposition (' + empfWaehrung + ') ueberschreitet das konfigurierte Limit (' + MAX_NON_EUR_EXPOSURE_PCT + '%)' });
    }
  }

  const einzelAnteilPct = ((Number(empf.position_value) || 0) / MODEL_PORTFOLIO_VALUE) * 100;
  if (einzelAnteilPct > MAX_SINGLE_POSITION_PCT) {
    blockers.push({ code: 'SINGLE_POSITION_LIMIT', message: 'Einzelposition ' + einzelAnteilPct.toFixed(2) + '% ueberschreitet das Limit (' + MAX_SINGLE_POSITION_PCT + '%)' });
  }

  if (offenePaperTrades.length + 1 > MAX_OPEN_POSITIONS) {
    blockers.push({ code: 'MAX_OPEN_POSITIONS', message: 'Maximale Anzahl offener Positionen (' + MAX_OPEN_POSITIONS + ') bereits erreicht' });
  }

  const richtungWert = offeneSumme('position_value', t => t.direction === empf.richtung || t.direction === (empf.richtung === 'kauf' ? 'long' : 'short')) + (Number(empf.position_value) || 0);
  if ((richtungWert / MODEL_PORTFOLIO_VALUE) * 100 > MAX_DIRECTIONAL_EXPOSURE_PCT) {
    blockers.push({ code: 'DIRECTIONAL_LIMIT', message: 'Richtungs-Exposition ueberschreitet das Limit (' + MAX_DIRECTIONAL_EXPOSURE_PCT + '%)' });
  }

  if (aktuellerDrawdownPct > MAX_PORTFOLIO_DRAWDOWN_PCT) {
    blockers.push({ code: 'DRAWDOWN_LIMIT', message: 'Aktueller Portfolio-Drawdown (' + aktuellerDrawdownPct.toFixed(2) + '%) ueberschreitet das Limit (' + MAX_PORTFOLIO_DRAWDOWN_PCT + '%) - keine neuen Eroeffnungen' });
  }

  const candReturns = dailyReturns(ticker);
  let maxCorr = null, maxCorrTicker = null;
  for (const t of offenePaperTrades) {
    if (t.ticker === ticker) continue;
    const otherReturns = dailyReturns(t.ticker);
    const corr = pearson(candReturns, otherReturns);
    if (corr !== null && (maxCorr === null || Math.abs(corr) > Math.abs(maxCorr))) { maxCorr = corr; maxCorrTicker = t.ticker; }
  }
  if (maxCorr !== null && Math.abs(maxCorr) > MAX_PAIRWISE_CORRELATION) {
    blockers.push({ code: 'CORRELATION_LIMIT', message: 'Hohe Korrelation (' + maxCorr.toFixed(2) + ') zu bereits offener Position ' + maxCorrTicker });
  }

  const approved = blockers.length === 0;
  // FIX 2026-08-01 (Fehleranalyse E3): Reihenfolge und Portfoliozustand vor/nach dieser
  // Entscheidung zusaetzlich zum bisherigen Gesamtrisiko-Paar als kompaktes Snapshot-JSON
  // sichern (sql/039 ergaenzt die Spalten).
  const stateSnapshot = {
    sequence_index: sequenceIndex,
    open_positions_before: offenePaperTrades.length,
    open_positions_after: offenePaperTrades.length + (approved ? 1 : 0),
    sektor_wert_before: round(sektorWert - (Number(empf.position_value) || 0), 2),
    sektor_wert_after: round(sektorWert, 2),
    richtung_wert_before: round(richtungWert - (Number(empf.position_value) || 0), 2),
    richtung_wert_after: round(richtungWert, 2),
    max_correlation: maxCorr, max_correlation_ticker: maxCorrTicker
  };
  output.push({
    _typ: 'portfolio_check', _dry_run: DRY_RUN,
    run_id, ticker, portfolio_approved: approved,
    portfolio_risk_before: portfolioRiskBefore, portfolio_risk_after: portfolioRiskAfter,
    blockers, config_snapshot: CFG, risk_model_version: RISK_MODEL_VERSION,
    sequence_index: sequenceIndex, state_snapshot: stateSnapshot
  });

  // FIX (Haertung Welle 1-3, Phasen 6+7, kritisch): Rueckschreiben nach recommendations -
  // vorher schrieb 14 NIE auf recommendations zurueck, eine abgelehnte Empfehlung blieb fuer
  // immer status='offen' (Widerspruch zu paper_trades.status=blocked). Dead-Letter-Eskalation:
  // eine Zeile, die trotz erfolgreicher Verarbeitung wiederholt als portfolio_pending geladen
  // wuerde (z.B. weil ein frueherer Schreibversuch fehlschlug), eskaliert nach
  // MAX_PORTFOLIO_CHECK_ATTEMPTS statt endlos erneut verarbeitet zu werden.
  const newAttempts = (Number(empf.portfolio_check_attempts) || 0) + 1;
  const attemptsEskaliert = newAttempts >= MAX_PORTFOLIO_CHECK_ATTEMPTS;
  if (attemptsEskaliert) {
    output.push({
      _typ: 'recommendation_status_update', recommendation_id: empf.id, run_id, ticker,
      new_status: 'portfolio_check_failed', attempts: newAttempts,
      blocked_reason: 'Nach ' + newAttempts + ' Laeufen weiterhin nicht aufgeloest - automatisch eskaliert.',
      risk_before: portfolioRiskBefore, risk_after: portfolioRiskAfter
    });
    output.push({
      _typ: 'workflow_error', workflow_name: '14 – Portfolio-Risiko und Paper-Trading',
      error_message: 'Empfehlung ' + empf.id + ' (' + ticker + ') hat seit ' + newAttempts + ' Laeufen keine aufgeloeste Portfolioentscheidung - automatisch eskaliert.',
      error_name: 'portfolio_check_failed'
    });
  } else {
    output.push({
      _typ: 'recommendation_status_update', recommendation_id: empf.id, run_id, ticker,
      new_status: approved ? 'offen' : 'portfolio_blocked', attempts: newAttempts,
      blocked_reason: approved ? null : blockers.map(b => b.code + ': ' + b.message).join('; '),
      risk_before: portfolioRiskBefore, risk_after: portfolioRiskAfter
    });
  }

  const tradeId = ticker + '-' + heute + '-' + empf.strategy;
  output.push({
    _typ: 'paper_trade_create', _dry_run: DRY_RUN,
    trade_id: tradeId, run_id, recommendation_id: empf.id, ticker, strategy: empf.strategy || 'unbekannt',
    direction: empf.richtung === 'kauf' ? 'long' : 'short',
    signal_created_at: empf.thesis_created_at || empf.letzte_aktualisierung, decision_time: empf.letzte_aktualisierung,
    entry_rule: 'zone_touch_conservative', planned_entry_zone_low: empf.entry_zone_low, planned_entry_zone_high: empf.entry_zone_high,
    stop_price_initial: empf.stop_price, target_price_initial: empf.target_price,
    time_stop_at: empf.time_stop_at, thesis_expires_at: empf.thesis_expires_at,
    theoretical_quantity: empf.theoretical_quantity, risk_amount: empf.risk_amount, position_value: empf.position_value,
    market_regime_at_entry: empf.combined_regime, opportunity_score_at_entry: empf.opportunity_score,
    risk_score_at_entry: empf.risk_score, evidence_confidence_at_entry: empf.evidence_confidence,
    configuration_version: JSON.stringify(empf.configuration_snapshot_json || {}).slice(0, 200),
    rule_version: empf.thesis_rule_version, execution_model_version: 'welle3-exec-v1', risk_model_version: RISK_MODEL_VERSION,
    status: approved ? 'proposed' : 'blocked', sektor: empf.sektor
  });

  // FIX 2026-08-01 (Fehleranalyse E2, kritisch): ohne dies wurde jeder Kandidat eines Laufs
  // gegen denselben (veralteten) offenePaperTrades-Ausgangszustand geprueft - mehrere neue
  // Empfehlungen desselben Tages konnten dadurch gemeinsam jedes Limit ueberschreiten, ohne
  // dass es auffiel (jede Einzelpruefung sah das Limit isoliert eingehalten). Ein genehmigter
  // Kandidat wird jetzt sofort mit den fuer die naechsten Pruefungen relevanten Feldern in den
  // lokalen Zustand aufgenommen, bevor die Schleife zum naechsten Kandidaten weitergeht.
  if (approved) {
    offenePaperTrades.push({
      ticker, sektor: empf.sektor,
      direction: empf.richtung === 'kauf' ? 'long' : 'short',
      risk_amount: empf.risk_amount, position_value: empf.position_value
    });
  }
}

return output.map(o => ({ json: o }));

// Workflow 14: ein gemeinsamer SQL-Dispatcher fuer alle Ausgabe-Item-Typen aus
// Job A (Portfoliopruefung/Trade-Anlage) und Job B (Ausfuehrung/Exit). Ein
// Dispatcher statt vieler einzelner SQL-bauen-Nodes haelt den Workflow-Graphen
// uebersichtlich - jeder Zweig ist unten als eigene, benannte Funktion klar
// abgegrenzt.

function pgStr(v) { return v === null || v === undefined || v === '' ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }
function pgNum(v) { return v === null || v === undefined || v === '' || isNaN(Number(v)) ? 'NULL' : Number(v); }
function pgBool(v) { if (v === true) return 'TRUE'; if (v === false) return 'FALSE'; return 'NULL'; }
function pgJsonb(v) { return (v === null || v === undefined) ? "'{}'::jsonb" : `'` + JSON.stringify(v).replace(/'/g, `''`) + `'::jsonb`; }

const j = $json;
let sql = 'SELECT 1;';

// FIX 2026-08-02 (Fehleranalyse B6): unabhaengige Verteidigung in der Tiefe - Items aus Job A,
// die trotz aktivem DRY_RUN entstanden sind (_dry_run:true), werden hier zusaetzlich blockiert,
// bevor irgendein Schreib-Statement gebaut wird. Job B (Ausfuehrung/Exit bestehender Trades)
// und Job C (Stressszenarien) taggen _dry_run nicht und sind bewusst NICHT betroffen - siehe
// Fehleranalyse B6 / docs/PORTFOLIORISIKO.md.
if (j._dry_run === true) {
  console.warn('DRY_RUN aktiv (B6-Verteidigung in der Tiefe): SQL-Schreibvorgang fuer _typ=' + j._typ + ' (ticker=' + (j.ticker || j.trade_id || '?') + ') unterdrueckt.');
} // FIX (Haertung Welle 1-3, Phasen 6+7, kritisch): recommendations bisher nie von 14
// zurueckgeschrieben - eine abgelehnte Empfehlung blieb fuer immer status='offen'. Der
// portfolio_check_id-Verweis wird per Subquery ueber (run_id, ticker) aufgeloest - die
// portfolio_check-Zeile fuer denselben Kandidaten wurde im selben Lauf bereits zuvor
// geschrieben (UNIQUE(run_id, ticker) seit Fehleranalyse B9 garantiert hoechstens eine Zeile).
if (j._typ === 'recommendation_status_update') {
  sql = `UPDATE trading.recommendations SET
    status = ${pgStr(j.new_status)},
    portfolio_check_id = (SELECT id FROM trading.portfolio_risk_checks WHERE run_id = ${pgStr(j.run_id)} AND ticker = ${pgStr(j.ticker)} ORDER BY checked_at DESC LIMIT 1),
    portfolio_checked_at = now(),
    portfolio_blocked_reason = ${pgStr(j.blocked_reason)},
    portfolio_risk_before = ${pgNum(j.risk_before)}, portfolio_risk_after = ${pgNum(j.risk_after)},
    portfolio_check_attempts = ${pgNum(j.attempts)},
    updated_at = now()
    WHERE id = ${pgNum(j.recommendation_id)} AND status = 'portfolio_pending';`;
}
else if (j._typ === 'portfolio_check') {
  // FIX 2026-08-01 (Fehleranalyse E3): sequence_index/portfolio_state_snapshot_json
  // zusaetzlich zum bisherigen Gesamtrisiko-Paar (sql/039).
  sql = `INSERT INTO trading.portfolio_risk_checks
    (run_id, ticker, portfolio_approved, portfolio_risk_before, portfolio_risk_after, blockers_json, config_snapshot_json, risk_model_version, sequence_index, portfolio_state_snapshot_json)
    VALUES (${pgStr(j.run_id)}, ${pgStr(j.ticker)}, ${pgBool(j.portfolio_approved)}, ${pgNum(j.portfolio_risk_before)}, ${pgNum(j.portfolio_risk_after)}, ${pgJsonb(j.blockers)}, ${pgJsonb(j.config_snapshot)}, ${pgStr(j.risk_model_version)}, ${pgNum(j.sequence_index)}, ${pgJsonb(j.state_snapshot)})
    ON CONFLICT (run_id, ticker) DO NOTHING;`;
}

else if (j._typ === 'paper_trade_create') {
  // FIX 2026-08-01 (Fehleranalyse E4): sektor mit in die Spaltenliste aufgenommen - vorher
  // wurde das Feld von Job A zwar gesetzt, aber beim INSERT verworfen, wodurch das
  // Sektorlimit in Job A (offeneSumme(...t.sektor===empf.sektor)) nie eine echte Zeile fand.
  sql = `INSERT INTO trading.paper_trades
    (trade_id, run_id, recommendation_id, ticker, strategy, direction, signal_created_at, decision_time, entry_rule,
     planned_entry_zone_low, planned_entry_zone_high, stop_price_initial, target_price_initial, stop_price_current,
     time_stop_at, thesis_expires_at, theoretical_quantity, risk_amount, position_value, market_regime_at_entry,
     opportunity_score_at_entry, risk_score_at_entry, evidence_confidence_at_entry, configuration_version, rule_version,
     execution_model_version, risk_model_version, status, sektor)
    VALUES (${pgStr(j.trade_id)}, ${pgStr(j.run_id)}, ${pgNum(j.recommendation_id)}, ${pgStr(j.ticker)}, ${pgStr(j.strategy)}, ${pgStr(j.direction)},
      ${pgStr(j.signal_created_at)}, ${pgStr(j.decision_time)}, ${pgStr(j.entry_rule)},
      ${pgNum(j.planned_entry_zone_low)}, ${pgNum(j.planned_entry_zone_high)}, ${pgNum(j.stop_price_initial)}, ${pgNum(j.target_price_initial)}, ${pgNum(j.stop_price_initial)},
      ${pgStr(j.time_stop_at)}, ${pgStr(j.thesis_expires_at)}, ${pgNum(j.theoretical_quantity)}, ${pgNum(j.risk_amount)}, ${pgNum(j.position_value)}, ${pgStr(j.market_regime_at_entry)},
      ${pgNum(j.opportunity_score_at_entry)}, ${pgNum(j.risk_score_at_entry)}, ${pgNum(j.evidence_confidence_at_entry)}, ${pgStr(j.configuration_version)}, ${pgStr(j.rule_version)},
      ${pgStr(j.execution_model_version)}, ${pgStr(j.risk_model_version)}, ${pgStr(j.status)}, ${pgStr(j.sektor)})
    ON CONFLICT (trade_id) DO NOTHING;`;
}

else if (j._typ === 'event') {
  sql = `INSERT INTO trading.paper_trade_events (trade_id, event_type, old_status, new_status, details_json)
    VALUES (${pgStr(j.trade_id)}, ${pgStr(j.event_type)}, ${pgStr(j.old_status)}, ${pgStr(j.new_status)}, ${pgJsonb(j.details)});`;
}

// FIX 2026-08-01 (Fehleranalyse E12, kritisch): 'fill_cluster' ersetzt die bisherigen drei
// getrennten Dispatches (trade_fill-UPDATE + 2x cost-INSERT + event-INSERT) durch EIN
// zusammenhaengendes BEGIN/COMMIT - vorher konnte z.B. das UPDATE gelingen und ein
// nachfolgender cost-INSERT unabhaengig fehlschlagen (onError:continueRegularOutput liess den
// Workflow trotzdem weiterlaufen), wodurch der Trade als gefuellt galt, die zugehoerigen
// Kosten aber dauerhaft fehlten. cost-INSERTs nutzen jetzt ON CONFLICT DO NOTHING
// (sql/039, UNIQUE(trade_id, cost_type)) - ein Retry nach einem Teilfehler dieser
// Transaktion legt keine doppelten Kostenzeilen an.
else if (j._typ === 'fill_cluster') {
  sql = `UPDATE trading.paper_trades SET
      status = ${pgStr(j.status)}, simulated_entry_time = ${pgStr(j.simulated_entry_time)}, simulated_entry_price = ${pgNum(j.simulated_entry_price)},
      stop_price_current = ${pgNum(j.stop_price_current)}, ambiguous_execution = ${pgBool(j.ambiguous_execution)},
      entry_fee_amount = ${pgNum(j.entry_fee_amount)}, entry_slippage_amount = ${pgNum(j.entry_slippage_amount)}, updated_at = now()
      WHERE trade_id = ${pgStr(j.trade_id)} AND status = 'proposed';
    INSERT INTO trading.paper_trade_costs (trade_id, cost_type, amount, model_name)
      VALUES (${pgStr(j.trade_id)}, 'entry_fee', ${pgNum(j.entry_fee_amount)}, 'fee_bps_v1')
      ON CONFLICT (trade_id, cost_type) DO NOTHING;
    INSERT INTO trading.paper_trade_costs (trade_id, cost_type, amount, model_name)
      VALUES (${pgStr(j.trade_id)}, 'entry_slippage', ${pgNum(j.entry_slippage_amount)}, 'slippage_bps_v1')
      ON CONFLICT (trade_id, cost_type) DO NOTHING;
    INSERT INTO trading.paper_trade_events (trade_id, event_type, old_status, new_status, details_json)
      VALUES (${pgStr(j.trade_id)}, 'filled', 'proposed', 'open', ${pgJsonb(j.event_details)});`;
}

else if (j._typ === 'trade_close_unfilled') {
  sql = `UPDATE trading.paper_trades SET status = 'expired_unfilled', updated_at = now() WHERE trade_id = ${pgStr(j.trade_id)} AND status = 'proposed';`;
}

// FIX 2026-08-01 (Fehleranalyse E8): ersetzt den frueheren 'trade_flag'-Zweig fuer
// Datenfehler - jetzt mit Retry-Zaehler statt dauerhaftem stillem Stillstand (sql/039).
else if (j._typ === 'data_error_flag') {
  sql = `UPDATE trading.paper_trades SET
    status = ${pgStr(j.status)}, data_quality_at_exit = 'invalid',
    data_error_count = ${pgNum(j.data_error_count)}, data_error_first_at = ${pgStr(j.data_error_first_at)}, data_error_last_at = ${pgStr(j.data_error_last_at)},
    updated_at = now()
    WHERE trade_id = ${pgStr(j.trade_id)};`;
}

// FIX 2026-08-01 (Fehleranalyse E8): Eskalation nach Ausschoepfung der Retries landet im
// bereits bestehenden zentralen Fehlerprotokoll (sql/005), sichtbar wie jeder andere
// Node-Fehler auch, statt spurlos zu verschwinden.
else if (j._typ === 'workflow_error') {
  sql = `INSERT INTO trading.workflow_errors (workflow_name, error_message, error_name)
    VALUES (${pgStr(j.workflow_name)}, ${pgStr(j.error_message)}, ${pgStr(j.error_name)});`;
}

else if (j._typ === 'cost') {
  sql = `INSERT INTO trading.paper_trade_costs (trade_id, cost_type, amount, model_name)
    VALUES (${pgStr(j.trade_id)}, ${pgStr(j.cost_type)}, ${pgNum(j.amount)}, ${pgStr(j.model_name)})
    ON CONFLICT (trade_id, cost_type) DO NOTHING;`;
}

else if (j._typ === 'valuation') {
  sql = `INSERT INTO trading.paper_trade_valuations (trade_id, valuation_date, mark_price, maximum_favorable_excursion, maximum_adverse_excursion)
    VALUES (${pgStr(j.trade_id)}, ${pgStr(j.valuation_date)}, ${pgNum(j.mark_price)}, ${pgNum(j.mfe_today)}, ${pgNum(j.mae_today)})
    ON CONFLICT (trade_id, valuation_date) DO UPDATE SET
      mark_price = EXCLUDED.mark_price,
      maximum_favorable_excursion = GREATEST(COALESCE(trading.paper_trade_valuations.maximum_favorable_excursion, 0), EXCLUDED.maximum_favorable_excursion),
      maximum_adverse_excursion = GREATEST(COALESCE(trading.paper_trade_valuations.maximum_adverse_excursion, 0), EXCLUDED.maximum_adverse_excursion);
    UPDATE trading.paper_trades SET
      maximum_favorable_excursion = GREATEST(COALESCE(maximum_favorable_excursion, 0), ${pgNum(j.mfe_today)}),
      maximum_adverse_excursion = GREATEST(COALESCE(maximum_adverse_excursion, 0), ${pgNum(j.mae_today)}),
      updated_at = now()
    WHERE trade_id = ${pgStr(j.trade_id)};`;
}

// FIX 2026-08-01 (Fehleranalyse E12, kritisch): 'close_cluster' ersetzt die bisherigen drei
// getrennten Dispatches (trade_close-UPDATE + 2x cost-INSERT) durch EIN BEGIN/COMMIT -
// gleiche Begruendung wie bei 'fill_cluster' oben. Enthaelt zusaetzlich die beim Fill
// gespeicherten Einstiegskosten NICHT erneut (die bleiben unveraendert auf der Zeile
// stehen, sql/039) - nur die Austrittskosten werden hier neu angelegt.
else if (j._typ === 'close_cluster') {
  sql = `UPDATE trading.paper_trades SET
      status = 'closed', exit_time = ${pgStr(j.exit_time)}, exit_price = ${pgNum(j.exit_price)}, exit_reason = ${pgStr(j.exit_reason)},
      exit_reasons_all_json = ${pgJsonb(j.exit_reasons_all)}, gross_pnl = ${pgNum(j.gross_pnl)}, net_pnl = ${pgNum(j.net_pnl)},
      return_pct = ${pgNum(j.return_pct)}, realized_r_multiple = ${pgNum(j.realized_r_multiple)}, holding_period_days = ${pgNum(j.holding_period_days)},
      ambiguous_execution = ${pgBool(j.ambiguous_execution)}, data_quality_at_exit = ${pgStr(j.data_quality_at_exit)}, updated_at = now()
      WHERE trade_id = ${pgStr(j.trade_id)} AND status = 'open';
    INSERT INTO trading.paper_trade_costs (trade_id, cost_type, amount, model_name)
      VALUES (${pgStr(j.trade_id)}, 'exit_fee', ${pgNum(j.exit_fee)}, 'fee_bps_v1')
      ON CONFLICT (trade_id, cost_type) DO NOTHING;
    INSERT INTO trading.paper_trade_costs (trade_id, cost_type, amount, model_name)
      VALUES (${pgStr(j.trade_id)}, 'exit_slippage', ${pgNum(j.exit_slippage)}, 'slippage_bps_v1')
      ON CONFLICT (trade_id, cost_type) DO NOTHING;
    INSERT INTO trading.paper_trade_events (trade_id, event_type, old_status, new_status, details_json)
      VALUES (${pgStr(j.trade_id)}, 'closed', 'open', 'closed', ${pgJsonb({ exitReason: j.exit_reason, exitReasonsAll: j.exit_reasons_all, ambiguous: j.ambiguous_execution, filledThisBar: j.filled_this_bar })});`;
}

else if (j._typ === 'stress_scenario') {
  sql = `INSERT INTO trading.stress_scenarios (run_id, scenario_name, assumptions_json, affected_positions_json, estimated_loss, loss_pct_of_portfolio, data_quality, model_version)
    VALUES (${pgStr(j.run_id)}, ${pgStr(j.scenario_name)}, ${pgJsonb(j.assumptions)}, ${pgJsonb(j.affected_positions)}, ${pgNum(j.estimated_loss)}, ${pgNum(j.loss_pct_of_portfolio)}, ${pgStr(j.data_quality)}, ${pgStr(j.model_version)});`;
}

return { json: { ...j, sql } };

// Workflow 14, JOB B (Welle 3, AP2+AP3+AP4): taegliche Ausfuehrungs-/Exit-
// Simulation fuer bestehende Paper Trades. Konservativ und deterministisch
// (Auftragsvorgabe) - siehe docs/AUSFUEHRUNGSMODELL.md fuer jede Annahme.
// Nutzt AUSSCHLIESSLICH Tageskerzen (open/high/low/close aus
// trading.stock_price_history, Welle 1) - keine Intraday-Daten vorhanden,
// AMBIGUOUS_BAR_POLICY regelt den Fall "Stop und Ziel in derselben Kerze".

function round(v, d = 4) { if (v === null || v === undefined || isNaN(v)) return null; return parseFloat(Number(v).toFixed(d)); }
function num(v) { const n = Number(v); return v === null || v === undefined || v === '' || isNaN(n) ? null : n; }
// FIX 2026-08-02 (Fehleranalyse B9): deterministisches Tagesdatum, bisher hatte Job B
// (anders als Job A/C) gar kein eigenes Datumskonzept - noetig als Dedup-Schluessel fuer
// paper_trade_events (business_date-Spalte, sql/045).
function getBusinessDate(date = new Date()) {
  return new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Berlin', year: 'numeric', month: '2-digit', day: '2-digit' }).format(date);
}
const heute = getBusinessDate();

const CFG = {};
for (const r of $('DB: Portfolio-Konfiguration laden (Exec)').all().map(i => i.json)) CFG[r.config_key] = Number(r.value_numeric);
const FEE_BPS = CFG.DEFAULT_FEES_BPS ?? 15;
const SLIPPAGE_BPS = CFG.DEFAULT_SLIPPAGE_BPS ?? 10;
// FIX 2026-08-01 (Fehleranalyse E10, mittel): aus pipeline_config lesbar statt reiner
// JS-Konstante - der bisherige Code-Kommentar "konfigurierbar dokumentiert" stimmte nicht,
// es gab keinen tatsaechlichen Konfigurationspfad.
const AMBIGUOUS_BAR_POLICY = CFG.AMBIGUOUS_BAR_POLICY_CODE === 2 ? 'conservative_target_first' : 'conservative_stop_first';
const EXECUTION_MODEL_VERSION = 'welle3-exec-v1';
// FIX 2026-08-01 (Fehleranalyse E8): Retry-Obergrenze fuer Trades ohne gueltige Tageskerze,
// bevor eskaliert (statt fuer immer stillschweigend liegenzubleiben) wird.
const MAX_DATA_ERROR_RETRIES = CFG.MAX_DATA_ERROR_RETRIES ?? 5;

const trades = $('DB: Ausstehende/offene Paper-Trades laden').all().map(i => i.json);
const barsRows = $('DB: Heutige Kerzen laden (Exec)').all().map(i => i.json);
const strategyRows = $('DB: Strategiesignale heute laden (Exec)').all().map(i => i.json);

const barByTicker = {}; for (const b of barsRows) barByTicker[String(b.symbol || '').trim()] = b;
const strategyByTicker = {};
for (const s of strategyRows) { const k = String(s.ticker || '').trim(); if (!strategyByTicker[k]) strategyByTicker[k] = []; strategyByTicker[k].push(s); }

function fee(value) { return round(value * (FEE_BPS / 10000), 2); }
function slippage(value) { return round(value * (SLIPPAGE_BPS / 10000), 2); }

const output = [];
const now = new Date();

for (const t of trades) {
  const bar = barByTicker[t.ticker];

  if (!bar || bar.open == null || bar.high == null || bar.low == null || bar.close == null) {
    if (t.status === 'open' || t.status === 'proposed') {
      // FIX 2026-08-01 (Fehleranalyse E8, kritisch): 'data_error' war bisher eine dauerhafte
      // Sackgasse - die Ladequery ("DB: Ausstehende/offene Paper-Trades laden") kennt diesen
      // Status nicht, ein einmal geflaggter Trade wurde nie wieder betrachtet. Jetzt echter
      // Retry-Zustand: Zaehler hochzaehlen, nach MAX_DATA_ERROR_RETRIES eskalieren
      // (data_error_final + Eintrag in trading.workflow_errors) statt endlos oder gar nicht
      // erneut zu versuchen.
      const newCount = (Number(t.data_error_count) || 0) + 1;
      const eskaliert = newCount >= MAX_DATA_ERROR_RETRIES;
      output.push({ json: {
        _typ: 'data_error_flag', trade_id: t.trade_id,
        status: eskaliert ? 'data_error_final' : 'data_error',
        data_error_count: newCount,
        data_error_first_at: t.data_error_first_at || now.toISOString(),
        data_error_last_at: now.toISOString(),
        // FIX (Haertung Welle 1-3, Phase 4): beim ERSTEN Eintritt (t.status ist noch
        // 'open'/'proposed') wird der aktuelle Status gesichert - bei einem wiederholten
        // Fehlschlag (t.status ist bereits 'data_error') bleibt der einmal gespeicherte Wert
        // unveraendert, sonst wuerde er durch 'data_error' selbst ueberschrieben.
        pre_data_error_status: t.status === 'data_error' ? t.pre_data_error_status : t.status
      } });
      output.push({ json: { _typ: 'event', trade_id: t.trade_id, event_type: eskaliert ? 'data_error_escalated' : 'data_error_flagged', old_status: t.status, new_status: eskaliert ? 'data_error_final' : t.status, details: { reason: 'keine gueltige Tageskerze heute', versuch: newCount }, business_date: heute } });
      if (eskaliert) {
        output.push({ json: {
          _typ: 'workflow_error', workflow_name: '14 – Portfolio-Risiko und Paper-Trading',
          error_message: 'Trade ' + t.trade_id + ' (' + t.ticker + ') hat seit ' + newCount + ' Laeufen keine gueltige Tageskerze - automatisch eskaliert, keine weiteren Versuche.',
          error_name: 'data_error_final'
        } });
      }
    }
    continue;
  }

  // FIX 2026-08-01 (Fehleranalyse C9, kritisch): eine Kerze aus einer noch laufenden
  // Boersensitzung darf nicht als finaler Tagesschluss fuer Fill-/Exit-Entscheidungen
  // verwendet werden. Haengt an "02"s data_quality_status - solange dort nur valid/invalid
  // unterschieden wird (siehe Fehleranalyse C6, noch offen), greift dieser Zweig nicht,
  // ist aber bereits vollstaendig vorbereitet.
  if (bar.data_quality_status === 'session_incomplete') {
    continue;
  }

  // FIX (Haertung Welle 1-3, Phase 4, kritisch): data_error war bisher eine dauerhafte
  // Sackgasse - die Ladequery kennt den Status jetzt (siehe oben), hier die eigentliche
  // Wiederherstellung. Bewusst konservativ: Status wird zurueckgesetzt, Fill-/Exit-Pruefung
  // erfolgt aber erst im naechsten Lauf (kein Vermischen von "Kerze war heute erstmals wieder
  // da" mit "Kerze fuer Fill-/Exit-Entscheidung heranziehen" im selben Schritt).
  if (t.status === 'data_error') {
    const restoredStatus = t.pre_data_error_status || 'open';
    output.push({ json: { _typ: 'data_error_recovered', trade_id: t.trade_id, restored_status: restoredStatus } });
    output.push({ json: { _typ: 'event', trade_id: t.trade_id, event_type: 'data_error_recovered', old_status: 'data_error', new_status: restoredStatus, details: { versuche_bis_wiederherstellung: t.data_error_count || 0 }, business_date: heute } });
    continue;
  }

  const open = num(bar.open), high = num(bar.high), low = num(bar.low), close = num(bar.close);
  const richtungLong = t.direction === 'long';
  let entryFeeForClose = null, entrySlippageForClose = null;
  let entryAmbiguous = false;
  let filledThisBar = false;

  // ------------------------------------------------------------
  // Status 'proposed' -> pruefen ob die Einstiegszone erreicht wurde
  // (AP2: ENTRY_EXECUTION_MODEL='zone_touch_conservative')
  // ------------------------------------------------------------
  if (t.status === 'proposed') {
    const zoneLow = num(t.planned_entry_zone_low), zoneHigh = num(t.planned_entry_zone_high);
    let gefuellt = false, fillPrice = null, ambiguous = false;
    if (zoneLow !== null && zoneHigh !== null) {
      const beruehrt = low <= zoneHigh && high >= zoneLow;
      if (beruehrt) {
        gefuellt = true;
        if (open >= zoneLow && open <= zoneHigh) {
          fillPrice = open; // Eroeffnung bereits in der Zone - realistischer Fuellkurs
        } else if (open < zoneLow) {
          // Gap unter die Zone (fuer Long guenstiger als geplant) - konservativ NICHT den
          // guenstigeren Kurs annehmen, sondern den Zonenrand (kein rueckwirkend optimaler Kurs).
          fillPrice = zoneLow;
        } else {
          // Eroeffnung ueber der Zone, aber im Tagesverlauf zurueck in die Zone gelaufen -
          // konservativ der fuer den Trade schlechteste Punkt der Zone.
          fillPrice = richtungLong ? zoneHigh : zoneLow;
          ambiguous = true; // aus Tageskerzen nicht rekonstruierbar, WANN exakt beruehrt wurde
        }
      }
    }
    if (gefuellt) {
      const entryFee = fee(fillPrice * t.theoretical_quantity);
      const entrySlippage = slippage(fillPrice * t.theoretical_quantity);
      output.push({ json: { _typ: 'fill_cluster', trade_id: t.trade_id, status: 'open', simulated_entry_time: now.toISOString(), simulated_entry_price: fillPrice, stop_price_current: t.stop_price_initial, ambiguous_execution: ambiguous, entry_fee_amount: entryFee, entry_slippage_amount: entrySlippage, event_details: { fillPrice, ambiguous }, business_date: heute } });
      // FIX 2026-08-01 (Fehleranalyse E9, kritisch): frueher endete dieser Zweig hier mit
      // "continue" - ein heute erstmals gefuellter Trade wurde NIE im selben Lauf auf Stop-/
      // Zielberuehrung derselben Kerze geprueft, sondern fruehestens naechsten Tag mit der
      // Kerze von morgen. Jetzt faellt der Trade lokal als 'open' durch in die Exit-Engine
      // unten - dieselbe Tageskerze wird sowohl fuer den Fill als auch fuer eine moegliche
      // Stop-/Zielberuehrung ausgewertet (Auftragsvorgabe: "pruefe anschliessend, ob auf
      // derselben Kerze auch Stop oder Ziel beruehrt wurde").
      t.status = 'open';
      t.simulated_entry_price = fillPrice;
      t.stop_price_current = t.stop_price_initial;
      entryFeeForClose = entryFee;
      entrySlippageForClose = entrySlippage;
      entryAmbiguous = ambiguous;
      filledThisBar = true;
    } else {
      // Nicht erreicht - Ablauf pruefen (Zeitstop oder Thesenablauf ohne Fuellung)
      const abgelaufen = (t.time_stop_at && new Date(t.time_stop_at) <= now) || (t.thesis_expires_at && new Date(t.thesis_expires_at) <= now);
      if (abgelaufen) {
        output.push({ json: { _typ: 'trade_close_unfilled', trade_id: t.trade_id, status: 'expired_unfilled' } });
        output.push({ json: { _typ: 'event', trade_id: t.trade_id, event_type: 'expired_unfilled', old_status: 'proposed', new_status: 'expired_unfilled', details: {}, business_date: heute } });
      }
      continue;
    }
  } else {
    // Bereits vorher (an einem frueheren Tag) gefuellt - Einstiegskosten stehen auf der
    // geladenen Zeile selbst (sql/039, seit dem Fill-Lauf gespeichert).
    entryFeeForClose = num(t.entry_fee_amount) || 0;
    entrySlippageForClose = num(t.entry_slippage_amount) || 0;
  }

  // ------------------------------------------------------------
  // Status 'open' (bereits vorher offen ODER heute gerade gefuellt) -> Exit-Engine
  // ------------------------------------------------------------
  if (t.status === 'open') {
    const entry = num(t.simulated_entry_price);
    const stop = num(t.stop_price_current || t.stop_price_initial);
    const target = num(t.target_price_initial);
    const qty = num(t.theoretical_quantity) || 0;

    // MFE/MAE dieser Kerze
    const favorable = richtungLong ? high - entry : entry - low;
    const adverse = richtungLong ? entry - low : high - entry;
    output.push({ json: { _typ: 'valuation', trade_id: t.trade_id, valuation_date: bar.trading_date, mark_price: close, mfe_today: round(favorable, 4), mae_today: round(adverse, 4) } });

    const stopBeruehrt = richtungLong ? low <= stop : high >= stop;
    const targetBeruehrt = richtungLong ? high >= target : low <= target;
    const exitReasonsAll = [];
    let exitReason = null, exitPrice = null, ambiguous = entryAmbiguous;

    // FIX (Haertung Welle 1-3, Phase 5, kritisch): Stop wurde bisher immer exakt zum
    // Stop-Preis simuliert, auch bei einer Kurspluecke ueber den Stop hinweg - unrealistisch
    // guenstig. Roh-Ausfuehrungspreis jetzt gap-bewusst: Long faellt bei Open < Stop auf Open
    // zurueck (schlechter als der Stop), Short bei Open > Stop auf Open (ebenfalls schlechter).
    // Ziel bleibt bewusst IMMER exakt der Zielkurs (kein rueckwirkend optimaler Gap-Kurs -
    // "Gap durch Ziel nicht automatisch zum optimalen Zielkurs abrechnen").
    function stopRawExitPrice() {
      if (richtungLong) return open < stop ? open : stop;
      return open > stop ? open : stop;
    }
    if (stopBeruehrt && targetBeruehrt) {
      ambiguous = true;
      exitReasonsAll.push('stop_loss', 'target_reached', 'ambiguous_execution');
      if (AMBIGUOUS_BAR_POLICY === 'conservative_stop_first') { exitReason = 'stop_loss'; exitPrice = stopRawExitPrice(); }
      else { exitReason = 'target_reached'; exitPrice = target; }
    } else if (stopBeruehrt) {
      exitReason = 'stop_loss'; exitPrice = stopRawExitPrice(); exitReasonsAll.push('stop_loss');
    } else if (targetBeruehrt) {
      exitReason = 'target_reached'; exitPrice = target; exitReasonsAll.push('target_reached');
    }

    if (!exitReason && t.time_stop_at && new Date(t.time_stop_at) <= now) { exitReason = 'time_stop'; exitPrice = close; exitReasonsAll.push('time_stop'); }
    if (!exitReason && t.thesis_expires_at && new Date(t.thesis_expires_at) <= now) { exitReason = 'thesis_expired'; exitPrice = close; exitReasonsAll.push('thesis_expired'); }
    if (!exitReason) {
      const strat = (strategyByTicker[t.ticker] || []).find(s => s.strategy === t.strategy);
      if (strat) {
        const stratDirection = strat.direction === 'long' ? 'long' : (strat.direction === 'short' ? 'short' : 'neutral');
        if (stratDirection !== 'neutral' && stratDirection !== t.direction) { exitReason = 'opposite_signal'; exitPrice = close; exitReasonsAll.push('opposite_signal'); }
      }
    }

    // FIX (Haertung Welle 1-3, Phase 5): Gap-Kennzahlen fuer Speicherung/Auswertung ableiten.
    const gapThroughStop = exitReason === 'stop_loss' && exitPrice !== stop;
    const gapAmount = gapThroughStop ? round(Math.abs(stop - exitPrice), 4) : 0;
    const executionQuality = !exitReason ? null
      : gapThroughStop ? 'gap_through_stop'
      : exitReason === 'stop_loss' ? 'exact_stop'
      : exitReason === 'target_reached' ? 'exact_target'
      : 'close_fallback';
    if (filledThisBar && exitReason) {
      // Dokumentierte Mehrdeutigkeit: Fill und Exit auf derselben Kerze - aus einer
      // Tageskerze ist nicht rekonstruierbar, ob der Exit-Grund den Fill zeitlich ueberhaupt
      // noch erreicht haette (Fehleranalyse E9).
      ambiguous = true;
      exitReasonsAll.push('same_bar_fill_and_exit');
    }

    if (exitReason) {
      const grossPnl = richtungLong ? (exitPrice - entry) * qty : (entry - exitPrice) * qty;
      const exitFee = fee(exitPrice * qty);
      const exitSlippage = slippage(exitPrice * qty);
      // FIX (Haertung Welle 1-3, Phase 5): effektiver Ausstiegspreis je Aktie - Roh-Preis
      // minus (Slippage+Gebuehren) in ungueltiger Richtung, rein informativ/Audit-Feld;
      // net_pnl selbst bleibt unveraendert ueber die bereits etablierte Formel berechnet
      // (Fehleranalyse E6/E7), um keine Regression an bereits getesteten Kennzahlen zu riskieren.
      const effectiveExitPrice = qty > 0 ? round(exitPrice - ((exitFee + exitSlippage) / qty) * (richtungLong ? 1 : -1), 4) : exitPrice;
      // FIX 2026-08-01 (Fehleranalyse E7, kritisch): Einstiegskosten (Fee+Slippage, beim Fill
      // berechnet - entweder heute in diesem Lauf oder aus einem frueheren Lauf ueber
      // entry_fee_amount/entry_slippage_amount auf der Zeile) flossen bisher NIE in net_pnl
      // ein - nur die Austrittskosten wurden abgezogen. Jedes net_pnl war dadurch systematisch
      // um die Einstiegskosten zu hoch, was sich in return_pct/realized_r_multiple/Profit
      // Factor/Drawdown/Lernagenten-Gates fortpflanzte.
      // FIX 2026-08-02 (Welle-3-Abgleich, Fund 1/5): financing_cost war im Auftrag explizit als
      // Kennzahl gefordert, fehlte komplett. Aktuell immer 0 - kein Broker/Produkt mit
      // definiertem Finanzierungssatz wird simuliert (konsistent mit dem Hebelprodukt-
      // Disclaimer aus Phase 9: "kein konkretes Produkt - Finanzierungskosten selbst
      // pruefen"). Formel ist trotzdem vollstaendig (subtrahiert bereits), damit ein
      // spaeteres echtes Finanzierungsmodell ohne erneuten Formel-Umbau andocken kann.
      const financingCost = 0;
      const netPnl = round(grossPnl - (entryFeeForClose || 0) - (entrySlippageForClose || 0) - exitFee - exitSlippage - financingCost, 2);
      const returnPct = entry > 0 ? round((netPnl / (entry * qty)) * 100, 3) : null;
      const riskAmount = num(t.risk_amount);
      const rMultiple = riskAmount && riskAmount > 0 ? round(netPnl / riskAmount, 3) : null;
      const holdingDays = t.simulated_entry_time ? round((now.getTime() - new Date(t.simulated_entry_time).getTime()) / 86400000, 2) : (filledThisBar ? 0 : null);

      output.push({ json: { _typ: 'close_cluster', trade_id: t.trade_id, status: 'closed', exit_time: now.toISOString(), exit_price: exitPrice, exit_reason: exitReason, exit_reasons_all: exitReasonsAll, gross_pnl: round(grossPnl, 2), net_pnl: netPnl, return_pct: returnPct, realized_r_multiple: rMultiple, holding_period_days: holdingDays, ambiguous_execution: ambiguous, data_quality_at_exit: bar.data_quality_status || 'valid', exit_fee: exitFee, exit_slippage: exitSlippage, financing_cost: financingCost, filled_this_bar: filledThisBar, business_date: heute, raw_exit_price: exitPrice, effective_exit_price: effectiveExitPrice, gap_through_stop: gapThroughStop, gap_amount: gapAmount, execution_quality: executionQuality, execution_model_version: EXECUTION_MODEL_VERSION } });
    }
  }
}

return output;

// Workflow 14: ein gemeinsamer SQL-Dispatcher fuer alle Ausgabe-Item-Typen aus
// Job A (Portfoliopruefung/Trade-Anlage) und Job B (Ausfuehrung/Exit). Ein
// Dispatcher statt vieler einzelner SQL-bauen-Nodes haelt den Workflow-Graphen
// uebersichtlich - jeder Zweig ist unten als eigene, benannte Funktion klar
// abgegrenzt.

function pgStr(v) { return v === null || v === undefined || v === '' ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }
function pgNum(v) { return v === null || v === undefined || v === '' || isNaN(Number(v)) ? 'NULL' : Number(v); }
function pgBool(v) { if (v === true) return 'TRUE'; if (v === false) return 'FALSE'; return 'NULL'; }
function pgJsonb(v) { return (v === null || v === undefined) ? "'{}'::jsonb" : `'` + JSON.stringify(v).replace(/'/g, `''`) + `'::jsonb`; }

const j = $json;
let sql = 'SELECT 1;';

if (j._typ === 'portfolio_check') {
  // FIX 2026-08-01 (Fehleranalyse E3): sequence_index/portfolio_state_snapshot_json
  // zusaetzlich zum bisherigen Gesamtrisiko-Paar (sql/039).
  sql = `INSERT INTO trading.portfolio_risk_checks
    (run_id, ticker, portfolio_approved, portfolio_risk_before, portfolio_risk_after, blockers_json, config_snapshot_json, risk_model_version, sequence_index, portfolio_state_snapshot_json)
    VALUES (${pgStr(j.run_id)}, ${pgStr(j.ticker)}, ${pgBool(j.portfolio_approved)}, ${pgNum(j.portfolio_risk_before)}, ${pgNum(j.portfolio_risk_after)}, ${pgJsonb(j.blockers)}, ${pgJsonb(j.config_snapshot)}, ${pgStr(j.risk_model_version)}, ${pgNum(j.sequence_index)}, ${pgJsonb(j.state_snapshot)});`;
}

else if (j._typ === 'paper_trade_create') {
  // FIX 2026-08-01 (Fehleranalyse E4): sektor mit in die Spaltenliste aufgenommen - vorher
  // wurde das Feld von Job A zwar gesetzt, aber beim INSERT verworfen, wodurch das
  // Sektorlimit in Job A (offeneSumme(...t.sektor===empf.sektor)) nie eine echte Zeile fand.
  sql = `INSERT INTO trading.paper_trades
    (trade_id, run_id, recommendation_id, ticker, strategy, direction, signal_created_at, decision_time, entry_rule,
     planned_entry_zone_low, planned_entry_zone_high, stop_price_initial, target_price_initial, stop_price_current,
     time_stop_at, thesis_expires_at, theoretical_quantity, risk_amount, position_value, market_regime_at_entry,
     opportunity_score_at_entry, risk_score_at_entry, evidence_confidence_at_entry, configuration_version, rule_version,
     execution_model_version, risk_model_version, status, sektor)
    VALUES (${pgStr(j.trade_id)}, ${pgStr(j.run_id)}, ${pgNum(j.recommendation_id)}, ${pgStr(j.ticker)}, ${pgStr(j.strategy)}, ${pgStr(j.direction)},
      ${pgStr(j.signal_created_at)}, ${pgStr(j.decision_time)}, ${pgStr(j.entry_rule)},
      ${pgNum(j.planned_entry_zone_low)}, ${pgNum(j.planned_entry_zone_high)}, ${pgNum(j.stop_price_initial)}, ${pgNum(j.target_price_initial)}, ${pgNum(j.stop_price_initial)},
      ${pgStr(j.time_stop_at)}, ${pgStr(j.thesis_expires_at)}, ${pgNum(j.theoretical_quantity)}, ${pgNum(j.risk_amount)}, ${pgNum(j.position_value)}, ${pgStr(j.market_regime_at_entry)},
      ${pgNum(j.opportunity_score_at_entry)}, ${pgNum(j.risk_score_at_entry)}, ${pgNum(j.evidence_confidence_at_entry)}, ${pgStr(j.configuration_version)}, ${pgStr(j.rule_version)},
      ${pgStr(j.execution_model_version)}, ${pgStr(j.risk_model_version)}, ${pgStr(j.status)}, ${pgStr(j.sektor)})
    ON CONFLICT (trade_id) DO NOTHING;`;
}

else if (j._typ === 'event') {
  sql = `INSERT INTO trading.paper_trade_events (trade_id, event_type, old_status, new_status, details_json, business_date)
    VALUES (${pgStr(j.trade_id)}, ${pgStr(j.event_type)}, ${pgStr(j.old_status)}, ${pgStr(j.new_status)}, ${pgJsonb(j.details)}, ${pgStr(j.business_date)})
    ON CONFLICT (trade_id, event_type, business_date) DO NOTHING;`;
}

// FIX 2026-08-01 (Fehleranalyse E12, kritisch): 'fill_cluster' ersetzt die bisherigen drei
// getrennten Dispatches (trade_fill-UPDATE + 2x cost-INSERT + event-INSERT) durch EIN
// zusammenhaengendes BEGIN/COMMIT - vorher konnte z.B. das UPDATE gelingen und ein
// nachfolgender cost-INSERT unabhaengig fehlschlagen (onError:continueRegularOutput liess den
// Workflow trotzdem weiterlaufen), wodurch der Trade als gefuellt galt, die zugehoerigen
// Kosten aber dauerhaft fehlten. cost-INSERTs nutzen jetzt ON CONFLICT DO NOTHING
// (sql/039, UNIQUE(trade_id, cost_type)) - ein Retry nach einem Teilfehler dieser
// Transaktion legt keine doppelten Kostenzeilen an.
else if (j._typ === 'fill_cluster') {
  sql = `UPDATE trading.paper_trades SET
      status = ${pgStr(j.status)}, simulated_entry_time = ${pgStr(j.simulated_entry_time)}, simulated_entry_price = ${pgNum(j.simulated_entry_price)},
      stop_price_current = ${pgNum(j.stop_price_current)}, ambiguous_execution = ${pgBool(j.ambiguous_execution)},
      entry_fee_amount = ${pgNum(j.entry_fee_amount)}, entry_slippage_amount = ${pgNum(j.entry_slippage_amount)},
      extreme_price_since_entry = ${pgNum(j.extreme_price_since_entry)}, trail_distance = ${pgNum(j.trail_distance)}, updated_at = now()
      WHERE trade_id = ${pgStr(j.trade_id)} AND status = 'proposed';
    INSERT INTO trading.paper_trade_costs (trade_id, cost_type, amount, model_name)
      VALUES (${pgStr(j.trade_id)}, 'entry_fee', ${pgNum(j.entry_fee_amount)}, 'fee_bps_v1')
      ON CONFLICT (trade_id, cost_type) DO NOTHING;
    INSERT INTO trading.paper_trade_costs (trade_id, cost_type, amount, model_name)
      VALUES (${pgStr(j.trade_id)}, 'entry_slippage', ${pgNum(j.entry_slippage_amount)}, 'slippage_bps_v1')
      ON CONFLICT (trade_id, cost_type) DO NOTHING;
    INSERT INTO trading.paper_trade_events (trade_id, event_type, old_status, new_status, details_json, business_date)
      VALUES (${pgStr(j.trade_id)}, 'filled', 'proposed', 'open', ${pgJsonb(j.event_details)}, ${pgStr(j.business_date)})
      ON CONFLICT (trade_id, event_type, business_date) DO NOTHING;`;
}

else if (j._typ === 'trade_close_unfilled') {
  sql = `UPDATE trading.paper_trades SET status = 'expired_unfilled', updated_at = now() WHERE trade_id = ${pgStr(j.trade_id)} AND status = 'proposed';`;
}

// FIX 2026-08-01 (Fehleranalyse E8): ersetzt den frueheren 'trade_flag'-Zweig fuer
// Datenfehler - jetzt mit Retry-Zaehler statt dauerhaftem stillem Stillstand (sql/039).
else if (j._typ === 'data_error_flag') {
  sql = `UPDATE trading.paper_trades SET
    status = ${pgStr(j.status)}, data_quality_at_exit = 'invalid',
    data_error_count = ${pgNum(j.data_error_count)}, data_error_first_at = ${pgStr(j.data_error_first_at)}, data_error_last_at = ${pgStr(j.data_error_last_at)},
    pre_data_error_status = ${pgStr(j.pre_data_error_status)},
    updated_at = now()
    WHERE trade_id = ${pgStr(j.trade_id)};`;
}
// FIX (Haertung Welle 1-3, Phase 4): Wiederherstellung nach data_error - Status wird aus dem
// live in der DB gespeicherten pre_data_error_status restauriert (nicht aus dem moeglicherweise
// veralteten In-Memory-Wert dieses Laufs), Fehlerzaehler/Marker werden zurueckgesetzt.
else if (j._typ === 'data_error_recovered') {
  sql = `UPDATE trading.paper_trades SET
    status = COALESCE(pre_data_error_status, 'open'), pre_data_error_status = NULL,
    data_error_count = 0, data_quality_at_exit = NULL, updated_at = now()
    WHERE trade_id = ${pgStr(j.trade_id)} AND status = 'data_error';`;
}

// FIX 2026-08-01 (Fehleranalyse E8): Eskalation nach Ausschoepfung der Retries landet im
// bereits bestehenden zentralen Fehlerprotokoll (sql/005), sichtbar wie jeder andere
// Node-Fehler auch, statt spurlos zu verschwinden.
else if (j._typ === 'workflow_error') {
  sql = `INSERT INTO trading.workflow_errors (workflow_name, error_message, error_name)
    VALUES (${pgStr(j.workflow_name)}, ${pgStr(j.error_message)}, ${pgStr(j.error_name)});`;
}

else if (j._typ === 'cost') {
  sql = `INSERT INTO trading.paper_trade_costs (trade_id, cost_type, amount, model_name)
    VALUES (${pgStr(j.trade_id)}, ${pgStr(j.cost_type)}, ${pgNum(j.amount)}, ${pgStr(j.model_name)})
    ON CONFLICT (trade_id, cost_type) DO NOTHING;`;
}

else if (j._typ === 'valuation') {
  sql = `INSERT INTO trading.paper_trade_valuations (trade_id, valuation_date, mark_price, maximum_favorable_excursion, maximum_adverse_excursion)
    VALUES (${pgStr(j.trade_id)}, ${pgStr(j.valuation_date)}, ${pgNum(j.mark_price)}, ${pgNum(j.mfe_today)}, ${pgNum(j.mae_today)})
    ON CONFLICT (trade_id, valuation_date) DO UPDATE SET
      mark_price = EXCLUDED.mark_price,
      maximum_favorable_excursion = GREATEST(COALESCE(trading.paper_trade_valuations.maximum_favorable_excursion, 0), EXCLUDED.maximum_favorable_excursion),
      maximum_adverse_excursion = GREATEST(COALESCE(trading.paper_trade_valuations.maximum_adverse_excursion, 0), EXCLUDED.maximum_adverse_excursion);
    UPDATE trading.paper_trades SET
      maximum_favorable_excursion = GREATEST(COALESCE(maximum_favorable_excursion, 0), ${pgNum(j.mfe_today)}),
      maximum_adverse_excursion = GREATEST(COALESCE(maximum_adverse_excursion, 0), ${pgNum(j.mae_today)}),
      updated_at = now()
    WHERE trade_id = ${pgStr(j.trade_id)};`;
}

// FIX 2026-08-01 (Fehleranalyse E12, kritisch): 'close_cluster' ersetzt die bisherigen drei
// getrennten Dispatches (trade_close-UPDATE + 2x cost-INSERT) durch EIN BEGIN/COMMIT -
// gleiche Begruendung wie bei 'fill_cluster' oben. Enthaelt zusaetzlich die beim Fill
// gespeicherten Einstiegskosten NICHT erneut (die bleiben unveraendert auf der Zeile
// stehen, sql/039) - nur die Austrittskosten werden hier neu angelegt.
else if (j._typ === 'close_cluster') {
  sql = `UPDATE trading.paper_trades SET
      status = 'closed', exit_time = ${pgStr(j.exit_time)}, exit_price = ${pgNum(j.exit_price)}, exit_reason = ${pgStr(j.exit_reason)},
      exit_reasons_all_json = ${pgJsonb(j.exit_reasons_all)}, gross_pnl = ${pgNum(j.gross_pnl)}, net_pnl = ${pgNum(j.net_pnl)},
      return_pct = ${pgNum(j.return_pct)}, realized_r_multiple = ${pgNum(j.realized_r_multiple)}, holding_period_days = ${pgNum(j.holding_period_days)},
      ambiguous_execution = ${pgBool(j.ambiguous_execution)}, data_quality_at_exit = ${pgStr(j.data_quality_at_exit)}, financing_cost = ${pgNum(j.financing_cost)},
      raw_exit_price = ${pgNum(j.raw_exit_price)}, effective_exit_price = ${pgNum(j.effective_exit_price)}, gap_through_stop = ${pgBool(j.gap_through_stop)}, gap_amount = ${pgNum(j.gap_amount)}, execution_quality = ${pgStr(j.execution_quality)},
      updated_at = now()
      WHERE trade_id = ${pgStr(j.trade_id)} AND status = 'open';
    INSERT INTO trading.paper_trade_costs (trade_id, cost_type, amount, model_name)
      VALUES (${pgStr(j.trade_id)}, 'exit_fee', ${pgNum(j.exit_fee)}, 'fee_bps_v1')
      ON CONFLICT (trade_id, cost_type) DO NOTHING;
    INSERT INTO trading.paper_trade_costs (trade_id, cost_type, amount, model_name)
      VALUES (${pgStr(j.trade_id)}, 'exit_slippage', ${pgNum(j.exit_slippage)}, 'slippage_bps_v1')
      ON CONFLICT (trade_id, cost_type) DO NOTHING;
    INSERT INTO trading.paper_trade_events (trade_id, event_type, old_status, new_status, details_json, business_date)
      VALUES (${pgStr(j.trade_id)}, 'closed', 'open', 'closed', ${pgJsonb({ exitReason: j.exit_reason, exitReasonsAll: j.exit_reasons_all, ambiguous: j.ambiguous_execution, filledThisBar: j.filled_this_bar })}, ${pgStr(j.business_date)})
      ON CONFLICT (trade_id, event_type, business_date) DO NOTHING;`;
}

// WF14-Migration (TRADING_ENGINE_MIGRATION.md Abschnitt 7): neuer Schreibpfad fuer den
// Job-B-Engine-Pfad - eine offene, nicht ausgestoppte Position hatte im alten Pfad NIE einen
// Grund, stop_price_current/extreme_price_since_entry neu zu schreiben (der Stop aendert sich
// dort nie intraday). Der Trailing-Stop braucht das jeden Tag, auch wenn sich nichts bewegt hat.
else if (j._typ === 'trailing_stop_update') {
  sql = `UPDATE trading.paper_trades SET
    stop_price_current = ${pgNum(j.stop_price_current)}, extreme_price_since_entry = ${pgNum(j.extreme_price_since_entry)}, updated_at = now()
    WHERE trade_id = ${pgStr(j.trade_id)} AND status = 'open';`;
}

else if (j._typ === 'stress_scenario') {
  sql = `INSERT INTO trading.stress_scenarios (run_id, scenario_name, assumptions_json, affected_positions_json, estimated_loss, loss_pct_of_portfolio, data_quality, model_version)
    VALUES (${pgStr(j.run_id)}, ${pgStr(j.scenario_name)}, ${pgJsonb(j.assumptions)}, ${pgJsonb(j.affected_positions)}, ${pgNum(j.estimated_loss)}, ${pgNum(j.loss_pct_of_portfolio)}, ${pgStr(j.data_quality)}, ${pgStr(j.model_version)});`;
}

return { json: { ...j, sql } };

// Workflow 14, JOB C (Welle 3, AP6): einfache, transparente Stressszenarien.
// Bewusst simple Annahmen statt eines vorgetaeuschten komplexen Modells
// (Auftragsvorgabe) - jede Annahme ist unten im Code benannt und in
// docs/PORTFOLIORISIKO.md dokumentiert.

function round(v, d = 2) { if (v === null || v === undefined || isNaN(v)) return null; return parseFloat(Number(v).toFixed(d)); }
function num(v) { const n = Number(v); return v === null || v === undefined || v === '' || isNaN(n) ? null : n; }
function getBusinessDate(date = new Date()) { return new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Berlin', year: 'numeric', month: '2-digit', day: '2-digit' }).format(date); }

const CFG = {};
for (const r of $('DB: Portfolio-Konfiguration laden (Stress)').all().map(i => i.json)) CFG[r.config_key] = Number(r.value_numeric);
const MODEL_PORTFOLIO_VALUE = CFG.MODEL_PORTFOLIO_VALUE ?? 100000;
const MODEL_VERSION = 'welle3-stress-v1';
// FIX 2026-08-02 (Fehleranalyse B9): analog zu Job A - deterministisch statt Date.now(),
// damit UNIQUE(run_id, scenario_name) auf stress_scenarios greift.
const run_id = 'stress-' + getBusinessDate();

const offenePositionen = $('DB: Offene Paper-Trades laden (Stress)').all().map(i => i.json);
const dataQuality = offenePositionen.length > 0 ? 'valid' : 'limited';

// Annahme: die Aktie bewegt sich 1:1 mit dem angenommenen Index-/Sektor-Schock
// (kein echtes Beta pro Ticker verfuegbar - konservative, transparent benannte
// Vereinfachung, siehe docs/PORTFOLIORISIKO.md). Fuer Short-Positionen wird ein
// negativer Marktschock zum Gewinn, daher hier als Verlust gedeckelt auf 0.
function position_value_loss(pos, pctMove) { return num(pos.position_value) * (pctMove / 100); }

function scenario(name, assumptions, computeFn) {
  let totalLoss = 0;
  const affected = [];
  for (const pos of offenePositionen) {
    const loss = computeFn(pos);
    if (loss !== 0) { totalLoss += loss; affected.push({ ticker: pos.ticker, direction: pos.direction, loss: round(loss, 2) }); }
  }
  return { _typ: 'stress_scenario', run_id, scenario_name: name, assumptions, affected_positions: affected, estimated_loss: round(totalLoss, 2), loss_pct_of_portfolio: round((totalLoss / MODEL_PORTFOLIO_VALUE) * 100, 3), data_quality: dataQuality, model_version: MODEL_VERSION };
}

const output = [];

output.push(scenario('referenzindex_minus_3pct', 'Alle Positionen bewegen sich 1:1 mit einem angenommenen -3% Indexschock (kein Einzel-Beta verfuegbar).', pos => pos.direction === 'long' ? position_value_loss(pos, -3) : -Math.max(0, position_value_loss(pos, -3))));
output.push(scenario('referenzindex_minus_5pct', 'Wie oben, -5% Indexschock.', pos => pos.direction === 'long' ? position_value_loss(pos, -5) : -Math.max(0, position_value_loss(pos, -5))));
output.push(scenario('referenzindex_minus_10pct', 'Wie oben, -10% Indexschock.', pos => pos.direction === 'long' ? position_value_loss(pos, -10) : -Math.max(0, position_value_loss(pos, -10))));

// FIX 2026-08-02 (Welle-3-Abgleich, Fund 3/5): vorher wurde der Sektorschock unabhaengig vom
// tatsaechlichen Sektor auf ALLE offenen Positionen angewendet - funktional identisch zu
// einem weiteren Indexschock, kein zusaetzlicher diagnostischer Wert. sektor existiert seit
// Fehleranalyse E4 (2026-08-01) auf paper_trades - jetzt ein Szenario JE tatsaechlich
// gehaltenem Sektor, andere Sektoren bleiben in diesem Szenario unbetroffen.
const distinctSektoren = [...new Set(offenePositionen.map(p => p.sektor).filter(Boolean))];
if (distinctSektoren.length === 0) {
  output.push(scenario('sektor_minus_7pct', 'Keine offenen Positionen mit bekanntem Sektor - Sektor-Stressszenario aktuell nicht anwendbar.', pos => 0));
} else {
  for (const sektor of distinctSektoren) {
    output.push(scenario('sektor_minus_7pct_' + sektor, 'Positionen im Sektor ' + sektor + ' bewegen sich 1:1 mit einem -7% Sektorschock (kein Einzel-Beta verfuegbar), andere Sektoren bleiben in diesem Szenario unbetroffen.', pos => pos.sektor !== sektor ? 0 : (pos.direction === 'long' ? position_value_loss(pos, -7) : -Math.max(0, position_value_loss(pos, -7)))));
  }
}

output.push(scenario('waehrungsschock', 'Alle Bestandsticker sind EUR-denominiert (XETRA) - ein EUR/USD-Schock hat auf das aktuelle Datenuniversum keine direkte Wirkung. Schema/Berechnung vorbereitet fuer kuenftige nicht-EUR-Positionen.', pos => 0));

output.push(scenario('volatilitaetssprung', 'Angenommene Verdopplung der Tagesvolatilitaet fuehrt zu einer zusaetzlichen ungeplanten Bewegung von einer weiteren geplanten Stop-Distanz gegen die Position (grobe, transparent benannte Naeherung ohne Options-/Vega-Modell).', pos => {
  const stopDist = Math.abs(num(pos.simulated_entry_price || pos.stop_price_initial) - num(pos.stop_price_initial));
  const qty = num(pos.theoretical_quantity) || 0;
  return -1 * stopDist * qty;
}));

output.push(scenario('gap_durch_stop', 'Jede offene Position gapt beim Stop um eine weitere Stop-Distanz durch (realistisches Gap-Risiko bei Tageskerzen ohne garantierte Ausfuehrung exakt am Stop).', pos => {
  const stopDist = Math.abs(num(pos.simulated_entry_price || pos.stop_price_initial) - num(pos.stop_price_initial));
  const qty = num(pos.theoretical_quantity) || 0;
  return -1 * stopDist * qty;
}));

output.push({ _typ: 'stress_scenario', run_id, scenario_name: 'gleichzeitige_mehrfach_stopausloesung', assumptions: 'Alle offenen Positionen erreichen gleichzeitig ihren initialen Stop (Extremfall, z.B. Markt-weiter Crash) - Summe aller geplanten Risikobetraege.', affected_positions: offenePositionen.map(p => ({ ticker: p.ticker, direction: p.direction, loss: round(-1 * (num(p.risk_amount) || 0), 2) })), estimated_loss: round(-1 * offenePositionen.reduce((s, p) => s + (num(p.risk_amount) || 0), 0), 2), loss_pct_of_portfolio: round((-1 * offenePositionen.reduce((s, p) => s + (num(p.risk_amount) || 0), 0) / MODEL_PORTFOLIO_VALUE) * 100, 3), data_quality: dataQuality, model_version: MODEL_VERSION });

return output.map(o => ({ json: o }));

// Workflow 14: ein gemeinsamer SQL-Dispatcher fuer alle Ausgabe-Item-Typen aus
