      maximum_adverse_excursion = GREATEST(COALESCE(trading.paper_trade_valuations.maximum_adverse_excursion, 0), EXCLUDED.maximum_adverse_excursion);
    UPDATE trading.paper_trades SET
      maximum_favorable_excursion = GREATEST(COALESCE(maximum_favorable_excursion, 0), ${pgNum(j.mfe_today)}),
      maximum_adverse_excursion = GREATEST(COALESCE(maximum_adverse_excursion, 0), ${pgNum(j.mae_today)}),
      updated_at = now()
    WHERE trade_id = ${pgStr(j.trade_id)};`;
}

