    ON CONFLICT (run_id, scenario_name) DO NOTHING;`;
}

return { json: { ...j, sql } };

function summarizeJob(dispatcherName, execName) {
  let dispatched = [];
  let executed = [];
  try { dispatched = $(dispatcherName).all().map(i => i.json); } catch (e) {}
  try { executed = $(execName).all(); } catch (e) {}
  const real = dispatched.filter(d => d.sql && d.sql.trim() !== 'SELECT 1;');
  const errors = executed.filter(i => i.json && i.json.error).map(i => String((i.json.error && (i.json.error.message || i.json.error)) || ''));
  return { attempted: dispatched.length, processed: real.length, dryRunSkipped: dispatched.length - real.length, failed: errors.length, errors };
}

const jobA = summarizeJob('SQL bauen (Dispatcher A)', 'SQL ausfuehren (A)');
const jobB = summarizeJob('SQL bauen (Dispatcher B)', 'SQL ausfuehren (B)');
const jobC = summarizeJob('SQL bauen (Dispatcher C)', 'SQL ausfuehren (C)');

const processed = jobA.processed + jobB.processed + jobC.processed;
const failed = jobA.failed + jobB.failed + jobC.failed;
const attempted = jobA.attempted + jobB.attempted + jobC.attempted;
const successful = attempted - failed;

let status;
if (attempted === 0) status = 'skipped';
else if (failed === 0) status = 'success';
else if (successful === 0) status = 'failed';
else status = 'partial_failure';

const errors = [
  ...jobA.errors.map(m => ({ node: 'SQL ausfuehren (A)', message: m })),
  ...jobB.errors.map(m => ({ node: 'SQL ausfuehren (B)', message: m })),
  ...jobC.errors.map(m => ({ node: 'SQL ausfuehren (C)', message: m }))
];

let runId = null;
try {
  const jobCItems = $('Job C: Stressszenarien berechnen').all().map(i => i.json);
  runId = (jobCItems.find(i => i.run_id) || {}).run_id || null;
