const DRY_RUN = dryRunRow && dryRunRow.value_bool !== null && dryRunRow.value_bool !== undefined ? dryRunRow.value_bool === true : true;

// FIX (Dry-Run-Vergleich 2026-09-02): "DB: Offene Paper-Trades laden" hat alwaysOutputData -
// bei 0 echten offenen Trades kommt ein Phantom-Item ({}) statt eines leeren Arrays. Der alte
// Job-A-Pfad toleriert das stillschweigend (leere Werte tragen 0 zu Summen bei), aber dieser
// Pfad serialisiert offenePaperTrades direkt als Engine-Payload (open_positions) - ein Item
// ohne ticker/direction verletzt dort die Pydantic-Validierung (422). Gleicher Filter wie bei
// neueEmpfehlungen oben.
const offenePaperTrades = $('DB: Offene Paper-Trades laden').all().map(i => i.json).filter(t => t && t.ticker != null);
const geschlossenePaperTrades = $('DB: Geschlossene Paper-Trades laden (Drawdown)').all().map(i => i.json).filter(t => t && t.trade_id != null);
const regimeRows = $('DB: Marktregime laden (Portfolio)').all().map(i => i.json);
const priceRows = $('DB: Kursverlauf laden (Korrelation)').all().map(i => i.json);
const strategyStatusRows = $('DB: Strategie-Status laden').all().map(i => i.json);
const regionWaehrungRows = $('DB: Ticker-Region-Waehrung laden').all().map(i => i.json);
const regionByTicker = {}, waehrungByTicker = {};
for (const r of regionWaehrungRows) { regionByTicker[r.ticker] = r.region; waehrungByTicker[r.ticker] = r.currency; }

const regimeByRegion = {}; for (const r of regimeRows) regimeByRegion[r.region] = r;
const strategyAktivByName = {}; for (const s of strategyStatusRows) strategyAktivByName[s.strategy] = s.aktiv === true || s.aktiv === 'true';

const priceByTicker = {};
for (const p of priceRows) { const k = String(p.symbol || '').trim(); if (!priceByTicker[k]) priceByTicker[k] = []; priceByTicker[k].push(p); }
for (const k of Object.keys(priceByTicker)) priceByTicker[k].sort((a, b) => String(a.trading_date).localeCompare(String(b.trading_date)));
function dailyReturns(ticker) {
  const rows = (priceByTicker[ticker] || []).slice(-(CORRELATION_LOOKBACK_DAYS + 1));
  const closes = rows.map(r => Number(r.close)).filter(v => !isNaN(v));
  const rets = [];
  for (let i = 1; i < closes.length; i++) if (closes[i - 1] > 0) rets.push((closes[i] - closes[i - 1]) / closes[i - 1]);
  return rets;
}

geschlossenePaperTrades.sort((a, b) => String(a.exit_time).localeCompare(String(b.exit_time)));
let equity = MODEL_PORTFOLIO_VALUE, peak = MODEL_PORTFOLIO_VALUE;
for (const t of geschlossenePaperTrades) {
  equity += Number(t.net_pnl) || 0;
  if (equity > peak) peak = equity;
}
const aktuellerDrawdownPct = peak > 0 ? ((peak - equity) / peak) * 100 : 0;

function offeneSumme(feld, filterFn) {
  return offenePaperTrades.filter(filterFn || (() => true)).reduce((sum, t) => sum + (Number(t[feld]) || 0), 0);
}

function sortKey(e) {
  return [
    e.is_theoretical === false ? 0 : 1,
    -(Number(e.opportunity_score) || 0),
    -(Number(e.reward_risk_ratio) || 0),
    -(Number(e.evidence_confidence) || 0),
    String(e.ticker || '')
  ];
}
neueEmpfehlungen.sort((a, b) => {
  const ka = sortKey(a), kb = sortKey(b);
  for (let i = 0; i < ka.length; i++) {
    if (ka[i] < kb[i]) return -1;
    if (ka[i] > kb[i]) return 1;
  }
  return 0;
});

const riskCfgApi = {
  model_portfolio_value: MODEL_PORTFOLIO_VALUE, max_risk_per_trade_pct: MAX_RISK_PER_TRADE_PCT,
  max_total_open_risk_pct: MAX_TOTAL_OPEN_RISK_PCT, max_sector_exposure_pct: MAX_SECTOR_EXPOSURE_PCT,
  max_single_position_pct: MAX_SINGLE_POSITION_PCT, max_open_positions: MAX_OPEN_POSITIONS,
  max_directional_exposure_pct: MAX_DIRECTIONAL_EXPOSURE_PCT, max_portfolio_drawdown_pct: MAX_PORTFOLIO_DRAWDOWN_PCT,
  max_pairwise_correlation: MAX_PAIRWISE_CORRELATION, max_region_exposure_pct: MAX_REGION_EXPOSURE_PCT,
  max_non_eur_exposure_pct: MAX_NON_EUR_EXPOSURE_PCT, stress_risk_reduction_factor: STRESS_RISK_REDUCTION_FACTOR,
  max_position_value_pct: MAX_POSITION_VALUE_PCT, min_reward_risk_ratio: MIN_REWARD_RISK_RATIO
};
const feeModelApi = {
  kind: 'mini_future', mini_future_leverage: MINI_FUTURE_LEVERAGE, mini_future_spread_pct: MINI_FUTURE_SPREAD_PCT,
  mini_future_financing_pct_pa: MINI_FUTURE_FINANCING_PCT_PA, fee_bps: FEE_BPS, slippage_bps: SLIPPAGE_BPS
};

const output = [];
let sequenceIndex = 0;
for (const empf of neueEmpfehlungen) {
  sequenceIndex++;
  const ticker = empf.ticker;
  const region = empf.market_regime_region || 'Europa';
  const regime = regimeByRegion[region] || null;
  const istStress = !!(regime && regime.combined_regime === 'stress');
  const direction = empf.richtung === 'kauf' ? 'long' : 'short';
  const empfRegion = regionByTicker[ticker] || 'global';
  const empfWaehrung = waehrungByTicker[ticker] || 'EUR';

  const blockers = [];
  if (empf.strategy && strategyAktivByName[empf.strategy] === false) {
    blockers.push({ code: 'STRATEGY_DEACTIVATED', message: 'Strategie ' + empf.strategy + ' ist ueber einen aktivierten Lernvorschlag global deaktiviert.' });
  }

  let sizing = null, approved = false;
  if (blockers.length === 0) {
    const entryPriceEstimate = (Number(empf.entry_zone_low) + Number(empf.entry_zone_high)) / 2;
    const signalApi = {
      strategy: empf.strategy || 'unbekannt', direction,
      raw_score: Number(empf.opportunity_score) || 0,
      entry_zone_low: num(empf.entry_zone_low), entry_zone_high: num(empf.entry_zone_high),
      stop_price: num(empf.stop_price), target_price: num(empf.target_price),
      expected_horizon_days: 0, rule_version: empf.thesis_rule_version || ''
    };
    const openPositionsApi = offenePaperTrades.map(t => ({
      ticker: t.ticker, direction: t.direction, quantity: Number(t.theoretical_quantity) || 0,
      position_value: Number(t.position_value) || 0, sektor: t.sektor || 'unbekannt',
      region: regionByTicker[t.ticker] || 'global', currency: waehrungByTicker[t.ticker] || 'EUR',
      risk_amount: Number(t.risk_amount) || 0
    }));
    const correlationData = {};
    correlationData[ticker] = dailyReturns(ticker);
    for (const t of offenePaperTrades) {
      if (!correlationData[t.ticker]) correlationData[t.ticker] = dailyReturns(t.ticker);
    }
    const payload = {
      ticker, signal: signalApi, entry_price_estimate: entryPriceEstimate,
      sektor: empf.sektor || 'unbekannt', region: empfRegion, currency: empfWaehrung,
      risk_cfg: riskCfgApi, fee_model: feeModelApi,
      portfolio: { cash: 0, positions_value: 0, total_equity: 0, peak_equity: 0, drawdown_pct: aktuellerDrawdownPct, open_positions: openPositionsApi },
      sizing_mode: 'clamp', is_stress_regime: istStress, correlation_data: correlationData
    };
    const result = await this.helpers.httpRequest({
      method: 'POST', url: ENGINE_BASE_URL + '/engine/portfolio/check-and-size',
      body: payload, json: true, timeout: 30000
    });
    sizing = result.sizing;
    approved = result.approved === true;
    if (sizing && sizing.blocked && sizing.reason) {
      blockers.push({ code: sizing.reason, message: 'Sizing-Veto: ' + sizing.reason });
    }
    for (const b of (result.blockers || [])) {
      blockers.push({ code: b.limit_name, message: b.reason });
    }
  }

  const risikoVorher = offeneSumme('risk_amount');
  const risikoKandidat = approved && sizing ? sizing.risk_amount : (Number(empf.risk_amount) || 0);
  const portfolioRiskBefore = round(risikoVorher / MODEL_PORTFOLIO_VALUE, 5);
  const portfolioRiskAfter = round((risikoVorher + risikoKandidat) / MODEL_PORTFOLIO_VALUE, 5);

  const stateSnapshot = {
    sequence_index: sequenceIndex,
    open_positions_before: offenePaperTrades.length,
    open_positions_after: offenePaperTrades.length + (approved ? 1 : 0),
    sizing_mode: 'clamp',
    clamped: !!(sizing && sizing.clamped),
    clamp_reason: sizing && sizing.clamped ? sizing.reason : null
  };
  output.push({
    _typ: 'portfolio_check', _dry_run: DRY_RUN,
    run_id, ticker, portfolio_approved: approved,
    portfolio_risk_before: portfolioRiskBefore, portfolio_risk_after: portfolioRiskAfter,
    blockers, config_snapshot: CFG, risk_model_version: RISK_MODEL_VERSION,
    sequence_index: sequenceIndex, state_snapshot: stateSnapshot
  });

  const newAttempts = (Number(empf.portfolio_check_attempts) || 0) + 1;
  const attemptsEskaliert = newAttempts >= MAX_PORTFOLIO_CHECK_ATTEMPTS;
  if (attemptsEskaliert) {
    output.push({
      _typ: 'recommendation_status_update', recommendation_id: empf.id, run_id, ticker,
      new_status: 'portfolio_check_failed', attempts: newAttempts,
      blocked_reason: 'Nach ' + newAttempts + ' Laeufen weiterhin nicht aufgeloest - automatisch eskaliert.',
      risk_before: portfolioRiskBefore, risk_after: portfolioRiskAfter
    });
    output.push({
      _typ: 'workflow_error', workflow_name: '14 – Portfolio-Risiko und Paper-Trading',
      error_message: 'Empfehlung ' + empf.id + ' (' + ticker + ') hat seit ' + newAttempts + ' Laeufen keine aufgeloeste Portfolioentscheidung - automatisch eskaliert.',
      error_name: 'portfolio_check_failed'
    });
  } else {
    output.push({
      _typ: 'recommendation_status_update', recommendation_id: empf.id, run_id, ticker,
      new_status: approved ? 'offen' : 'portfolio_blocked', attempts: newAttempts,
      blocked_reason: approved ? null : blockers.map(b => b.code + ': ' + b.message).join('; '),
      risk_before: portfolioRiskBefore, risk_after: portfolioRiskAfter
    });
  }

  const tradeId = ticker + '-' + heute + '-' + empf.strategy;
  const finalQuantity = approved && sizing ? sizing.quantity : empf.theoretical_quantity;
  const finalRiskAmount = approved && sizing ? sizing.risk_amount : empf.risk_amount;
  const finalPositionValue = approved && sizing ? sizing.position_value : empf.position_value;
  output.push({
    _typ: 'paper_trade_create', _dry_run: DRY_RUN,
    trade_id: tradeId, run_id, recommendation_id: empf.id, ticker, strategy: empf.strategy || 'unbekannt',
    direction,
    signal_created_at: empf.thesis_created_at || empf.letzte_aktualisierung, decision_time: empf.letzte_aktualisierung,
    entry_rule: 'zone_touch_conservative', planned_entry_zone_low: empf.entry_zone_low, planned_entry_zone_high: empf.entry_zone_high,
    stop_price_initial: empf.stop_price, target_price_initial: empf.target_price,
    time_stop_at: empf.time_stop_at, thesis_expires_at: empf.thesis_expires_at,
    // WICHTIG: trotz des Namens ist "theoretical_quantity" die Spalte, die Job B tatsaechlich
    // als auszufuehrende Stueckzahl liest (const qty = num(t.theoretical_quantity) - siehe
    // Job B) - es gibt keine separate "echte Menge"-Spalte auf paper_trades. Hier MUSS also
    // die (ggf. gekappte) finalQuantity stehen, NICHT sizing.theoretical_quantity (das waere
    // die ungekappte Engine-Zielgroesse) - sonst wuerde Job B die volle, ungekappte Menge
    // handeln und die Kappung waere wirkungslos. Die ungekappte Zielgroesse landet stattdessen
    // im NEUEN Audit-Feld theoretical_risk_amount (sql/080) - kein Stueckzahl-Aequivalent
    // dafuer noetig, der Risikobetrag genuegt als Audit-Spur.
    theoretical_quantity: finalQuantity,
    risk_amount: finalRiskAmount, position_value: finalPositionValue,
    theoretical_risk_amount: sizing ? sizing.theoretical_risk_amount : null,
    clamp_reason: sizing && sizing.clamped ? sizing.reason : null,
    market_regime_at_entry: empf.combined_regime, opportunity_score_at_entry: empf.opportunity_score,
    risk_score_at_entry: empf.risk_score, evidence_confidence_at_entry: empf.evidence_confidence,
    configuration_version: JSON.stringify(empf.configuration_snapshot_json || {}).slice(0, 200),
    rule_version: empf.thesis_rule_version, execution_model_version: 'welle3-exec-engine-v1', risk_model_version: RISK_MODEL_VERSION,
    status: approved ? 'proposed' : 'blocked', sektor: empf.sektor
  });

  if (approved) {
    offenePaperTrades.push({
      ticker, sektor: empf.sektor, direction,
      risk_amount: finalRiskAmount, position_value: finalPositionValue,
      theoretical_quantity: finalQuantity
    });
  }
}

return output.map(o => ({ json: o }));

// WF14-Migration (TRADING_ENGINE_MIGRATION.md Abschnitt 7): Engine-Pfad fuer Job B.
// Nur erreichbar, wenn "IF: Engine-Pfad nutzen? (Job B)" TRUE ergibt
// (pipeline_config.TRADING_ENGINE_EXECUTION_ENABLED=true). Der alte Node
// ("Job B: Ausfuehrung/Exit simulieren") bleibt unveraendert bestehen.
//
// Bringt zwei echte Verhaltensaenderungen mit (Nutzerentscheidung 2026-09-02):
// Mini-Future-Kostenmodell statt Gebuehren-Basispunkte, und ERSTMALS einen
// Trailing-Stop fuer Live-Paper-Trading (nur trend_following/breakout, siehe
// execution.py::_TRAILING_STRATEGIES).
//
// data_error-Retry-Logik, session_incomplete-Filterung und thesis_expires_at-
// Ablauf bleiben n8n-seitig (kein Engine-Aequivalent, siehe TRADING_ENGINE_
// MIGRATION.md Abschnitt 7 "n8n-seitig vs. Engine-seitig"). Fill/Exit/Trailing-
// Stop/PnL laufen ueber den Batch-Aufruf POST /engine/execution/process-trades.
//
// NEUER _typ 'trailing_stop_update': fuer eine offene, nicht ausgestoppte
// Position gibt es im alten Pfad KEINEN Schreibpfad (der Stop aendert sich nie
// intraday) - der Engine-Pfad muss stop_price_current/extreme_price_since_entry
// aber JEDEN Tag neu persistieren, auch wenn sich nichts bewegt hat (sql/079).

const ENGINE_BASE_URL = 'http://172.16.1.14:8099';

function round(v, d = 4) { if (v === null || v === undefined || isNaN(v)) return null; return parseFloat(Number(v).toFixed(d)); }
function num(v) { const n = Number(v); return v === null || v === undefined || v === '' || isNaN(n) ? null : n; }
function getBusinessDate(date = new Date()) {
  return new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Berlin', year: 'numeric', month: '2-digit', day: '2-digit' }).format(date);
}
const heute = getBusinessDate();

const CFG = {};
for (const r of $('DB: Portfolio-Konfiguration laden (Exec)').all().map(i => i.json)) CFG[r.config_key] = Number(r.value_numeric);
const FEE_BPS = CFG.DEFAULT_FEES_BPS ?? 15;
const SLIPPAGE_BPS = CFG.DEFAULT_SLIPPAGE_BPS ?? 10;
const AMBIGUOUS_BAR_POLICY = CFG.AMBIGUOUS_BAR_POLICY_CODE === 2 ? 'conservative_target_first' : 'conservative_stop_first';
const MAX_DATA_ERROR_RETRIES = CFG.MAX_DATA_ERROR_RETRIES ?? 5;
// Neu fuer den Engine-Pfad (sql-Widening der Konfig-Abfrage, siehe Node "DB:
// Portfolio-Konfiguration laden (Exec)").
const MINI_FUTURE_LEVERAGE = CFG.MINI_FUTURE_LEVERAGE ?? null;
const MINI_FUTURE_SPREAD_PCT = CFG.MINI_FUTURE_SPREAD_PCT ?? null;
const MINI_FUTURE_FINANCING_PCT_PA = CFG.MINI_FUTURE_FINANCING_PCT_PA ?? null;
const feeModelApi = {
  kind: 'mini_future', mini_future_leverage: MINI_FUTURE_LEVERAGE, mini_future_spread_pct: MINI_FUTURE_SPREAD_PCT,
  mini_future_financing_pct_pa: MINI_FUTURE_FINANCING_PCT_PA, fee_bps: FEE_BPS, slippage_bps: SLIPPAGE_BPS
};

// Defensiver Filter (Dry-Run-Vergleich 2026-09-02, siehe Job A (Engine)): bei 0 echten
// Treffern liefert dieser Node ein Phantom-Item ({}). Die bestehende status==='open'/
// 'proposed'-Pruefung unten faengt das strukturell schon ab (t.status waere undefined), dieser
// Filter macht es zusaetzlich explizit statt sich nur auf diesen Nebeneffekt zu verlassen.
const trades = $('DB: Ausstehende/offene Paper-Trades laden').all().map(i => i.json).filter(t => t && t.trade_id != null);
const barsRows = $('DB: Heutige Kerzen laden (Exec)').all().map(i => i.json);
const strategyRows = $('DB: Strategiesignale heute laden (Exec)').all().map(i => i.json);

const barByTicker = {}; for (const b of barsRows) barByTicker[String(b.symbol || '').trim()] = b;
const strategyByTicker = {};
for (const s of strategyRows) { const k = String(s.ticker || '').trim(); if (!strategyByTicker[k]) strategyByTicker[k] = []; strategyByTicker[k].push(s); }

const output = [];
const now = new Date();

// Vorverarbeitung: gleiche data_error/session_incomplete/data_error_recovered/
// thesis-Ablauf-Logik wie im alten Pfad (n8n-seitig, kein Engine-Aequivalent).
// Baut parallel die Liste der Items, die tatsaechlich an die Engine gehen.
const engineItems = [];
const barByTradeId = {};

for (const t of trades) {
  const bar = barByTicker[t.ticker];

  if (!bar || bar.open == null || bar.high == null || bar.low == null || bar.close == null) {
    if (t.status === 'open' || t.status === 'proposed') {
      const newCount = (Number(t.data_error_count) || 0) + 1;
      const eskaliert = newCount >= MAX_DATA_ERROR_RETRIES;
      output.push({ json: {
        _typ: 'data_error_flag', trade_id: t.trade_id,
        status: eskaliert ? 'data_error_final' : 'data_error',
        data_error_count: newCount,
        data_error_first_at: t.data_error_first_at || now.toISOString(),
        data_error_last_at: now.toISOString(),
        pre_data_error_status: t.status === 'data_error' ? t.pre_data_error_status : t.status
      } });
      output.push({ json: { _typ: 'event', trade_id: t.trade_id, event_type: eskaliert ? 'data_error_escalated' : 'data_error_flagged', old_status: t.status, new_status: eskaliert ? 'data_error_final' : t.status, details: { reason: 'keine gueltige Tageskerze heute', versuch: newCount }, business_date: heute } });
      if (eskaliert) {
        output.push({ json: {
          _typ: 'workflow_error', workflow_name: '14 – Portfolio-Risiko und Paper-Trading',
          error_message: 'Trade ' + t.trade_id + ' (' + t.ticker + ') hat seit ' + newCount + ' Laeufen keine gueltige Tageskerze - automatisch eskaliert, keine weiteren Versuche.',
          error_name: 'data_error_final'
        } });
      }
    }
    continue;
  }

  if (bar.data_quality_status === 'session_incomplete') continue;

  if (t.status === 'data_error') {
    const restoredStatus = t.pre_data_error_status || 'open';
    output.push({ json: { _typ: 'data_error_recovered', trade_id: t.trade_id, restored_status: restoredStatus } });
    output.push({ json: { _typ: 'event', trade_id: t.trade_id, event_type: 'data_error_recovered', old_status: 'data_error', new_status: restoredStatus, details: { versuche_bis_wiederherstellung: t.data_error_count || 0 }, business_date: heute } });
    continue;
  }

  if (t.status === 'proposed') {
    const zoneLow = num(t.planned_entry_zone_low), zoneHigh = num(t.planned_entry_zone_high);
    if (zoneLow === null || zoneHigh === null) continue;
    const beruehrt = bar.low <= zoneHigh && bar.high >= zoneLow;
    if (!beruehrt) {
      const abgelaufen = (t.time_stop_at && new Date(t.time_stop_at) <= now) || (t.thesis_expires_at && new Date(t.thesis_expires_at) <= now);
      if (abgelaufen) {
        output.push({ json: { _typ: 'trade_close_unfilled', trade_id: t.trade_id, status: 'expired_unfilled' } });
        output.push({ json: { _typ: 'event', trade_id: t.trade_id, event_type: 'expired_unfilled', old_status: 'proposed', new_status: 'expired_unfilled', details: {}, business_date: heute } });
      }
      continue;
    }
    engineItems.push({
      trade_id: t.trade_id, status: 'proposed',
      order: {
        ticker: t.ticker, direction: t.direction, entry_zone_low: zoneLow, entry_zone_high: zoneHigh,
        stop_price: num(t.stop_price_initial), target_price: num(t.target_price_initial), quantity: Number(t.theoretical_quantity) || 0,
        intended_execution_date: heute, strategy: t.strategy || '', sektor: t.sektor || 'unbekannt', region: 'global',
        risk_amount: num(t.risk_amount) || 0, time_stop_at: t.time_stop_at || null,
        theoretical_quantity: Number(t.theoretical_quantity) || 0, theoretical_risk_amount: num(t.theoretical_risk_amount) || 0,
        clamp_reason: t.clamp_reason || null
      },
      opposite_signal_today: false
    });
    barByTradeId[t.trade_id] = bar;
    continue;
  }

  if (t.status === 'open') {
    const strat = (strategyByTicker[t.ticker] || []).find(s => s.strategy === t.strategy);
    let oppositeSignalToday = false;
    if (strat) {
      const stratDirection = strat.direction === 'long' ? 'long' : (strat.direction === 'short' ? 'short' : 'neutral');
      oppositeSignalToday = stratDirection !== 'neutral' && stratDirection !== t.direction;
    }
    // Defensive Fallback (siehe sql/079-Kommentar): falls der Backfill/eine vorherige
    // Erstellung ueber den ALTEN Pfad diese Felder nie gesetzt hat, hier einmalig aus
    // Entry/Stop ableiten statt mit NULL an die Engine zu gehen.
    const entryPrice = num(t.simulated_entry_price);
    const stopInitial = num(t.stop_price_initial);
    const extremePrice = num(t.extreme_price_since_entry) ?? entryPrice;
    const trailDistance = num(t.trail_distance) ?? (entryPrice !== null && stopInitial !== null ? Math.abs(entryPrice - stopInitial) : 0);
    engineItems.push({
      trade_id: t.trade_id, status: 'open',
      trade: {
        trade_id: t.trade_id, ticker: t.ticker, direction: t.direction,
        entry_price: entryPrice, stop_price_current: num(t.stop_price_current) ?? stopInitial,
        target_price: num(t.target_price_initial), quantity: Number(t.theoretical_quantity) || 0,
        extreme_price_since_entry: extremePrice, trail_distance: trailDistance,
        entry_day: (t.simulated_entry_time || heute).slice(0, 10),
        time_stop_at: t.time_stop_at || null, strategy: t.strategy || '',
        sektor: t.sektor || 'unbekannt', region: 'global', risk_amount: num(t.risk_amount) || 0,
        theoretical_quantity: Number(t.theoretical_quantity) || 0, theoretical_risk_amount: num(t.theoretical_risk_amount) || 0,
        clamp_reason: t.clamp_reason || null
      },
      opposite_signal_today: oppositeSignalToday
    });
    barByTradeId[t.trade_id] = bar;
  }
}

if (engineItems.length > 0) {
  const bars_today = {};
  for (const [tradeId, bar] of Object.entries(barByTradeId)) {
    bars_today[bar.symbol] = { ticker: bar.symbol, trading_date: String(bar.trading_date).slice(0, 10), open: Number(bar.open), high: Number(bar.high), low: Number(bar.low), close: Number(bar.close), volume: Number(bar.volume) || 0 };
  }

  const response = await this.helpers.httpRequest({
    method: 'POST', url: ENGINE_BASE_URL + '/engine/execution/process-trades',
    body: { as_of: heute, items: engineItems, bars_today, fee_model: feeModelApi, ambiguous_bar_policy: AMBIGUOUS_BAR_POLICY },
    json: true, timeout: 30000
  });

  const resultByTradeId = {};
  for (const r of (response.results || [])) resultByTradeId[r.trade_id] = r;

  for (const item of engineItems) {
    const r = resultByTradeId[item.trade_id];
    if (!r) continue; // sollte nicht vorkommen - Engine liefert ein Ergebnis je Item

    if (item.status === 'proposed') {
      if (!r.fill) continue; // nicht getroffen in dieser Kerze - naechster Lauf versucht erneut, kein Persistenz-Zeile hier (wie alter Pfad)
      const t = item.order;
      const positionValue = r.fill.price * t.quantity;
      const entryFee = r.entry_fee != null ? r.entry_fee : 0;
      const entrySlippage = 0; // mini_future kennt keine separate Entry-Slippage (siehe backtest.py-Kommentar)
      output.push({ json: {
        _typ: 'fill_cluster', trade_id: item.trade_id, status: 'open', simulated_entry_time: now.toISOString(),
        simulated_entry_price: r.fill.price, stop_price_current: r.updated_trade ? r.updated_trade.stop_price_current : t.stop_price,
        extreme_price_since_entry: r.updated_trade ? r.updated_trade.extreme_price_since_entry : r.fill.price,
        ambiguous_execution: !!r.fill.ambiguous, entry_fee_amount: entryFee, entry_slippage_amount: entrySlippage,
        event_details: { fillPrice: r.fill.price, ambiguous: !!r.fill.ambiguous }, business_date: heute
      } });
      // Same-Bar Fill+Exit (siehe Modul-Docstring): die Engine liefert in diesem Fall
      // zusaetzlich exit/pnl im selben Ergebnis-Item.
      if (r.exit && r.pnl) {
        output.push({ json: buildCloseCluster(item.trade_id, r, true) });
      }
      continue;
    }

    // status === 'open'
    if (r.exit && r.pnl) {
      output.push({ json: buildCloseCluster(item.trade_id, r, false) });
    } else if (r.updated_trade) {
      // NEU: bisher gab es hierfuer keinen Schreibpfad (siehe Modul-Docstring) - der
      // Trailing-Stop braucht ihn, um sein "Gedaechtnis" ueber Tage hinweg zu behalten.
      output.push({ json: {
        _typ: 'trailing_stop_update', trade_id: item.trade_id,
        stop_price_current: r.updated_trade.stop_price_current,
        extreme_price_since_entry: r.updated_trade.extreme_price_since_entry
      } });
    }

    // Bewertung (MFE/MAE) bleibt n8n-seitig berechnet - trivial aus Bar+Entry, die
    // Engine liefert dafuer kein eigenes Feld zurueck.
    const bar = barByTradeId[item.trade_id];
    const entry = item.trade.entry_price;
    const richtungLong = item.trade.direction === 'long';
    if (bar && entry !== null) {
      const favorable = richtungLong ? bar.high - entry : entry - bar.low;
      const adverse = richtungLong ? entry - bar.low : bar.high - entry;
      output.push({ json: { _typ: 'valuation', trade_id: item.trade_id, valuation_date: bar.trading_date, mark_price: bar.close, mfe_today: round(favorable, 4), mae_today: round(adverse, 4) } });
    }
  }
}

function buildCloseCluster(tradeId, r, filledThisBar) {
  const exitReasonsAll = [r.exit.reason];
  if (filledThisBar) exitReasonsAll.push('same_bar_fill_and_exit');
  const gapThroughStop = !!r.exit.gap_through_stop;
  const executionQuality = gapThroughStop ? 'gap_through_stop' : (r.exit.reason === 'stop_loss' ? 'exact_stop' : (r.exit.reason === 'take_profit' || r.exit.reason === 'target_reached' ? 'exact_target' : 'close_fallback'));
  const gapAmount = gapThroughStop && r.updated_trade ? round(Math.abs(r.updated_trade.stop_price_current - r.exit.price), 4) : 0;
  const qty = r.updated_trade ? r.updated_trade.quantity : 0;
  const entry = r.updated_trade ? r.updated_trade.entry_price : null;
  const effectiveExitPrice = qty > 0 ? round(r.exit.price - ((r.pnl.exit_fee + r.pnl.exit_slippage) / qty) * (r.updated_trade && r.updated_trade.direction === 'long' ? 1 : -1), 4) : r.exit.price;
  const riskAmount = r.updated_trade ? r.updated_trade.risk_amount : null;
  const rMultiple = riskAmount && riskAmount > 0 ? round(r.pnl.net_pnl / riskAmount, 3) : null;
  const holdingDays = filledThisBar ? 0 : (r.updated_trade && r.updated_trade.entry_day ? round((now.getTime() - new Date(r.updated_trade.entry_day).getTime()) / 86400000, 2) : null);
  return {
    _typ: 'close_cluster', trade_id: tradeId, status: 'closed', exit_time: now.toISOString(), exit_price: r.exit.price,
    exit_reason: r.exit.reason === 'take_profit' ? 'target_reached' : r.exit.reason, exit_reasons_all: exitReasonsAll.map(x => x === 'take_profit' ? 'target_reached' : x),
    gross_pnl: round(r.pnl.gross_pnl, 2), net_pnl: round(r.pnl.net_pnl, 2),
    return_pct: entry && qty ? round((r.pnl.net_pnl / (entry * qty)) * 100, 3) : null,
    realized_r_multiple: rMultiple, holding_period_days: holdingDays,
    ambiguous_execution: !!r.exit.ambiguous || filledThisBar, data_quality_at_exit: 'valid',
    exit_fee: r.pnl.exit_fee, exit_slippage: r.pnl.exit_slippage, financing_cost: r.pnl.financing_cost,
    filled_this_bar: filledThisBar, business_date: heute, raw_exit_price: r.exit.price, effective_exit_price: effectiveExitPrice,
    gap_through_stop: gapThroughStop, gap_amount: gapAmount, execution_quality: executionQuality,
    execution_model_version: 'welle3-exec-engine-v1'
  };
}

return output;
